const ozBiology9Orta = <(String, String, List<String>, String)>[
  ('Gregor Mendel bezelye deneylerini bugün Çekya sınırları içinde kalan hangi kentteki manastırda yürütmüştür?', 'Brno (Brünn)', ['Graz (Steiermark)', 'Prag', 'Kraków'], 'Mendel, Brünn\'deki (bugünkü Brno) Augustinusçu Aziz Thomas Manastırı\'nın bahçesinde deneylerini yapmıştır.'),
  ('Mendel\'in kalıtım deneylerini yayımladığı ünlü makalesinin Türkçe karşılığı hangisidir?', 'Bitki Melezleri Üzerine Deneyler', ['Türlerin Kökeni Üzerine', 'Hayvan ve Bitkilerin Evcilleştirilmesi', 'Bezelyede Kromozom Davranışı'], 'Mendel\'in makalesi \'Versuche über Pflanzen-Hybriden\', yani \'Bitki Melezleri Üzerine Deneyler\' adını taşır.'),
  ('Mendel\'in deneylerinde kullandığı bahçe bezelyesinin bilimsel adı aşağıdakilerden hangisidir?', 'Pisum sativum', ['Phaseolus vulgaris', 'Lathyrus odoratus', 'Vicia faba'], 'Bahçe bezelyesi Pisum sativum\'dur; Lathyrus odoratus kokulu bezelye, Phaseolus fasulye, Vicia faba baklasıdır.'),
  ('Mendel\'in 1866\'da yayımlanan bulgularının yaklaşık 34 yıl boyunca değeri anlaşılmadan kalmasının en çok kabul gören nedenlerinden biri hangisidir?', 'Sayısal ve olasılığa dayalı yaklaşımın dönemin biyologlarına yabancı olması', ['Mendel\'in deneylerini hiç yayımlamamış olması', 'Bezelyenin o dönemde Avrupa\'da bilinmeyen ve yetiştirilmeyen bir bitki olması', 'Sonuçlarının deneylerle hemen çürütülmüş olması'], 'Mendel bulgularını yayımlamıştı; ancak oranlara ve olasılığa dayanan yorumu, dönemin betimleyici biyolojisi tarafından kavranmadı.'),
  ('Aşağıdaki bezelye karakterlerinden hangisi Mendel\'in incelediği yedi karakter arasında yer almaz?', 'Yaprak kenarının dişli ya da düz olması', ['Tohumun düz ya da buruşuk olması', 'Baklanın yeşil ya da sarı olması', 'Çiçeklerin gövde boyunca ya da uçta dizilmesi'], 'Mendel tohum biçimi ve rengi, çiçek rengi, çiçek konumu, bakla biçimi ve rengi ile gövde uzunluğunu incelemiştir; yaprak kenarı bunlardan değildir.'),
  ('Mendel\'in deneylerine önce yalnız tek bir karakteri izleyerek başlamasının yöntem açısından en önemli yararı neydi?', 'Sonuçları karıştırmadan açık sayısal oranlar elde edebilmek', ['Deneyleri daha kısa sürede bitirmek', 'Bitkilerin mutasyon geçirmesini önlemek', 'Çevre koşullarının bitkiler üzerindeki etkisini tamamen ortadan kaldırmak'], 'Tek karakterin izlenmesi, döllerin sınıflara ayrılıp sayılmasını kolaylaştırarak 3 : 1 gibi oranları görünür kıldı.'),
  ('Mendel\'in çaprazlamalarda yüzlerce, hatta binlerce döl sayması deneyin güvenilirliğine nasıl katkı sağlamıştır?', 'Şans sapmalarının etkisini azaltarak gerçek oranı ortaya çıkarmıştır', ['Mutasyonların sayısını artırmıştır', 'Baskın alellerin sayısını artırmıştır', 'Bitkilerin daha hızlı büyümesini ve daha çok tohum vermesini sağlamıştır'], 'Örnek büyüdükçe gözlenen oranlar beklenen olasılıklara yaklaşır; küçük örneklerde şans sapmaları büyük olur.'),
  ('Mendel\'in saf döl bezelye hatlarını elde etmek için başvurduğu yol aşağıdakilerden hangisidir?', 'Bitkileri birkaç kuşak kendileştirip özelliği hiç değişmeyenleri seçmek', ['Farklı bitkileri rastgele melezlemek', 'Tohumları farklı topraklarda yetiştirmek', 'Yalnız en uzun boylu ve en çok tohum veren bitkileri ayırıp tohuma bırakmak'], 'Birkaç kuşak kendileştirildiğinde hep aynı özelliği veren hatlar o karakter bakımından homozigottur.'),
  ('Heterozigot bir bezelyede (Tt) çekinik t aleli için aşağıdakilerden hangisi doğrudur?', 'Değişmeden kalır ve gametlerin yarısına aktarılır', ['Baskın alelin etkisiyle zamanla baskın alele dönüştürülür', 'Hücre bölünmesi sırasında yok edilir ve gametlere geçemez', 'Yalnız erkek gametlere aktarılır'], 'Baskınlık yalnız fenotipte kendini gösterme ile ilgilidir; t aleli bozulmadan kalır ve ayrılma ilkesine göre gametlerin yarısına geçer.'),
  ('Bir bireyin fenotipi için aşağıdaki ifadelerden hangisi doğrudur?', 'Genotipin çevreyle etkileşimi sonucunda ortaya çıkar', ['Yalnız baskın alellerce belirlenir', 'Yaşam boyunca hiç değişmez', 'Gametler aracılığıyla değişmeden doğrudan döllere aktarılır'], 'Döllere aktarılan fenotip değil genlerdir; fenotip, genotip ile çevre koşullarının birlikte etkisinin ürünüdür.'),
  ('Fenotipleri aynı olan iki bezelyenin genotipleri için hangisi her zaman doğru olur?', 'Genotipleri aynı da olabilir, farklı da olabilir', ['Genotipleri kesinlikle aynıdır ve ikisi de homozigottur', 'Genotipleri kesinlikle farklıdır', 'İkisi de heterozigottur'], 'Baskın fenotipli bireyler AA ya da Aa olabileceğinden aynı fenotip farklı genotiplerden doğabilir; çekinik fenotipte ise genotip tektir.'),
  ('Bir bitkide uzun boy (U) kısa boya (u) baskındır. Uu × uu çaprazlamasından 60 bitki elde edildiğinde 31 uzun ve 29 kısa bitki sayılıyor. Bu sonuç için en doğru yorum hangisidir?', 'Beklenen 1 : 1 oranına uygundur; küçük sapma şansa bağlıdır', ['Beklenen 3 : 1 oranından çok saptığı için deney mutlaka hatalı yapılmıştır', 'Uzunluk alelinin eksik baskın olduğunu gösterir', 'Kısa boy alelinin letal olduğunu gösterir'], 'Uu × uu\'dan beklenen 30 : 30\'dur; 31 : 29 bu orana çok yakındır ve fark şansla açıklanır.'),
  ('Mendel\'in ayrılma ilkesinin hücresel temeli mayozun hangi olayıyla açıklanır?', 'Homolog kromozomların farklı kutuplara çekilmesiyle', ['DNA\'nın eşlenmesiyle', 'Sitoplazmanın bölünmesiyle', 'Kardeş kromatitlerin aynı kutupta kalıp birlikte hareket etmesiyle'], 'Bir genin iki aleli homolog kromozomlarda bulunur; mayoz I\'de homologlar ayrıldığında aleller farklı gametlere gider.'),
  ('Genotipi AaBbCcDd olan ve genleri bağımsız açılan bir bireyin oluşturduğu gametlerin kaçta kaçı ABCD genotipinde olur?', '1/16', ['1/4', '1/8', '1/32'], 'Her lokus için baskın alelin gamete geçme olasılığı 1/2\'dir; (1/2)⁴ = 1/16.'),
  ('AaBbCc × aabbcc çaprazlamasında genler bağımsız açılıyorsa döllerde kaç farklı genotip ortaya çıkar?', '8', ['27', '6', '4'], 'aabbcc yalnız abc gameti verdiğinden döllerin genotip çeşidi, AaBbCc\'nin gamet çeşidi kadardır: 2³ = 8.'),
  ('Genotipi AaBb olan bir bireyin oluşturduğu gametlerden Ab gametinin oranı %25 olarak bulunuyor. Bu sonuç A ve B genleri hakkında neyi düşündürür?', 'Bağımsız açıldıklarını', ['Aynı kromozomda tam bağlı olduklarını', 'A\'nın B\'ye epistatik olduğunu', 'B\'nin letal olduğunu'], 'Bağımsız açılımda dört gamet çeşidi eşit oranda (%25) oluşur; tam bağlılıkta Ab hiç oluşmazdı.'),
  ('AaBbCc genotipli iki birey çaprazlanırsa (genler bağımsız) döllerin kaçta kaçı her üç gen bakımından da heterozigot olur?', '1/8', ['1/64', '1/4', '3/8'], 'Her lokusta heterozigot olma olasılığı 1/2\'dir; (1/2)³ = 1/8.'),
  ('AaBbCcDd × AaBbCcDd çaprazlamasında genler bağımsız açılıyor ve baskınlık tam ise dört karakter bakımından da çekinik fenotipli döl oluşma olasılığı nedir?', '1/256', ['1/16', '1/64', '1/128'], 'Her lokus için çekinik fenotip olasılığı 1/4\'tür; (1/4)⁴ = 1/256.'),
  ('AaBb × aabb çaprazlamasında (genler bağımsız) doğan döllerin kaçta kaçı ebeveynlerinden birinin genotipiyle aynı genotipe sahip olur?', '1/2', ['1/4', '3/4', '1/16'], 'Döller 1/4 AaBb, 1/4 Aabb, 1/4 aaBb ve 1/4 aabb\'dir; ebeveyn genotipleri AaBb ve aabb toplam 1/2 eder.'),
  ('AABBCC × aabbcc çaprazlamasıyla elde edilen F1 bireyleri kendi aralarında çaprazlanıyor. F2\'de AABBCC genotipli birey oluşma olasılığı nedir?', '1/64', ['1/8', '1/16', '1/27'], 'F1 AaBbCc\'dir; F2\'de her lokusta homozigot baskın olma olasılığı 1/4, üç lokus için (1/4)³ = 1/64.'),
  ('AaBbCc × AaBbCc çaprazlamasında (genler bağımsız, baskınlık tam) A ve B bakımından baskın, C bakımından çekinik fenotipli döllerin oranı nedir?', '9/64', ['27/64', '3/64', '3/16'], '3/4 × 3/4 × 1/4 = 9/64.'),
  ('İki taşıyıcı ebeveynin (Aa × Aa) üç çocuğundan ilk ikisinin hasta (aa), üçüncüsünün sağlıklı olma olasılığı nedir?', '3/64', ['9/64', '1/16', '27/64'], 'Sıra belirtildiği için olasılıklar yalnızca çarpılır: 1/4 × 1/4 × 3/4 = 3/64.'),
  ('Taşıyıcı (Aa) iki ebeveynin bir çocuğunun hem kız hem de otozomal çekinik hastalığa yakalanmış olma olasılığı nedir?', '1/8', ['1/4', '1/2', '1/16'], 'Kız olma 1/2, hasta olma 1/4; iki bağımsız olayın birlikte olasılığı 1/2 × 1/4 = 1/8.'),
  ('Dört çocuklu bir ailede çocukların ikisinin kız, ikisinin erkek olma olasılığı nedir?', '3/8', ['1/2', '1/4', '1/16'], 'Dört çocuktan ikisinin kız olduğu 6 farklı sıra vardır; 6 × (1/2)⁴ = 6/16 = 3/8.'),
  ('Test çaprazlamasında elde edilen döllerin fenotip çeşitleri ve oranları doğrudan neyi yansıtır?', 'Test edilen bireyin oluşturduğu gamet çeşitlerini ve oranlarını', ['Çekinik ebeveynin genotipindeki çeşitliliği ve onun gamet oranlarını', 'Ebeveynlerin yaşını ve sağlığını', 'Yalnızca çevre koşullarının etkisini'], 'Çekinik ebeveyn yalnız çekinik alel verdiğinden her dölün fenotipi, öteki ebeveynden gelen gametin içeriğini gösterir.'),
  ('Bezelye gibi kendi kendini dölleyebilen bir bitkide, baskın fenotipli bir bireyin homozigot mu heterozigot mu olduğunu anlamak için test çaprazlamasına seçenek olarak hangi yol kullanılabilir?', 'Bitkiyi kendileştirip döllerde çekinik fenotip çıkıp çıkmadığına bakmak', ['Bitkinin boyunu ölçmek', 'Bitkiyi farklı toprakta yetiştirmek', 'Bitkinin yalnız yapraklarını mikroskopta inceleyip hücre sayısını belirlemek'], 'Heterozigot bir bitki kendileştirildiğinde döllerin yaklaşık dörtte biri çekinik fenotip gösterir; homozigotta bu görülmez.'),
  ('AaBb ile karşılaştırılmak üzere genotipi bilinmeyen bir bitki aabb ile test çaprazlamasına sokuluyor ve döllerin tamamı iki karakter için de baskın fenotipte çıkıyor. Bitkinin genotipi büyük olasılıkla nedir?', 'İki gen bakımından da homozigot baskın', ['İki gen bakımından da heterozigot', 'A için homozigot, B için heterozigot', 'A için heterozigot, B için homozigot baskın'], 'Döllerin tamamının iki karakterde de baskın olması, bitkinin yalnız AB gameti ürettiğini, yani AABB olduğunu gösterir.'),
  ('Bir bitki aabb ile test çaprazlamasına sokuluyor. Döllerin yarısı A ve B bakımından baskın, yarısı A bakımından baskın B bakımından çekinik fenotipte çıkıyor. Test edilen bitkinin genotipi nedir?', 'A için homozigot baskın, B için heterozigot', ['A için heterozigot, B için homozigot baskın', 'İki gen bakımından da heterozigot', 'A için heterozigot, B için homozigot çekinik'], 'Döllerin hepsi A bakımından baskın olduğuna göre bitki AA\'dır; B için 1 : 1 açılım Bb olduğunu gösterir.'),
  ('İki çaprazlamanın döllerinde A geni için şu sonuçlar alınıyor: Birincisinde tüm döller baskın fenotipte, ikincisinde döllerin yarısı çekinik fenotipte. Aşağıdaki ebeveyn çiftlerinden hangisi sırasıyla bu iki sonucu verir?', 'Önce homozigot baskın × çekinik, sonra heterozigot × çekinik', ['Önce heterozigot × heterozigot, sonra homozigot baskın × çekinik', 'Önce heterozigot × çekinik, sonra heterozigot × heterozigot', 'Önce homozigot baskın × heterozigot, sonra heterozigot × heterozigot'], 'AA × aa döllerin tamamını Aa yapar; Aa × aa ise yarı baskın, yarı çekinik döl verir.'),
  ('Bir çaprazlamada döllerin tamamı A bakımından baskın fenotipli çıkıyor; B bakımından ise döllerin yarısı baskın, yarısı çekinik. Aşağıdaki ebeveyn çiftlerinden hangisi bu sonucu verebilir?', 'A için homozigot baskın ve B için heterozigot birey ile çift çekinik birey', ['İki gen için heterozigot birey ile çift çekinik birey', 'İki gen için heterozigot iki birey', 'A için heterozigot ve B için çekinik birey ile A için çekinik ve B için heterozigot birey'], 'A için hiç çekinik döl çıkmaması bir ebeveynin AA olmasını, B için 1 : 1 oranı Bb × bb çaprazlamasını gerektirir.'),
  ('Saf döl iki karakter bakımından baskın (AABB) bitkilerle iki karakter bakımından çekinik (aabb) bitkiler çaprazlanıp F2 elde ediliyor. F2\'deki bireylerin kaçta kaçı ebeveyn fenotiplerinden birine (çift baskın ya da çift çekinik) sahiptir?', '10/16', ['9/16', '6/16', '1/16'], 'F2\'de çift baskınlar 9/16, çift çekinikler 1/16\'dır; ikisinin toplamı 10/16 eder.'),
  ('AaBb × AaBb çaprazlamasında (genler bağımsız, baskınlık tam) çift baskın fenotipi veren kaç farklı genotip vardır?', '4', ['9', '2', '3'], 'A_ için AA ve Aa, B_ için BB ve Bb vardır; 2 × 2 = 4 genotip (AABB, AABb, AaBB, AaBb).'),
  ('Mendel\'in dihibrit çaprazlamalarında F2\'de 9 : 3 : 3 : 1 oranını elde etmesi hangi sonuca ulaşmasını sağlamıştır?', 'Renk ve biçim alellerinin gametlere bağımsız dağıldığına', ['Tohum rengi ve tohum biçiminin tek bir genle birlikte belirlendiğine', 'Çekinik alellerin F2\'de kaybolduğuna', 'Melezlerde özelliklerin karıştığına'], '9 : 3 : 3 : 1, iki ayrı 3 : 1 oranının çarpımıdır; bu da iki karakterin birbirinden bağımsız kalıtıldığını gösterir.'),
  ('Heterozigot (Aa) bir bitkiden başlanarak her kuşak kendileştirme yapılırsa üçüncü kendileştirme sonunda heterozigot bireylerin oranı ne olur?', '1/8', ['1/4', '1/2', '1/16'], 'Her kendileştirmede heterozigot oranı yarıya iner: 1/2, 1/4, 1/8.'),
  ('Tarımda saf hat elde etmek için uzun süre kendileştirme yapılmasının genetik sonucu hangisidir?', 'Lokusların büyük çoğunluğunda homozigotluğun artması', ['Yeni alellerin hızla ortaya çıkması', 'Heterozigotluğun her kuşak artması', 'Kromozom sayısının her kuşakta iki katına çıkması ve poliploidi oluşması'], 'Kendileştirme heterozigotluğu her kuşak yarıya indirir; birkaç kuşak sonra bitkiler büyük ölçüde homozigot olur.'),
  ('Uzun süre kendileştirilen ya da yakın akrabalar arasında çiftleştirilen hayvan ırklarında zayıflık ve verim düşüşü görülmesinin genetik açıklaması hangisidir?', 'Zararlı çekinik alellerin homozigot hâle gelme olasılığının artması', ['Baskın alellerin kendiliğinden çekinik alele dönüşmesi ve sayıca azalması', 'Kromozomların kısalması', 'Gamet oluşumunun tamamen durması'], 'Akrabalı üretimde homozigotluk arttığından gizli kalan zararlı çekinik aleller fenotipte ortaya çıkar; buna akrabalı üretim çöküntüsü denir.'),
  ('Bir çiftçi, iyi verim veren heterozigot bir domates bitkisinin özelliklerini hiç değiştirmeden çoğaltmak istiyor. Genetik açıdan en uygun yöntem hangisidir?', 'Çelik ya da doku kültürü gibi eşeysiz yollarla çoğaltmak', ['Bitkiyi kendileştirip tohumlarını ekmek', 'Bitkiyi saf çekinik bir bitkiyle çaprazlamak', 'Bitkiyi her yıl farklı ve verimli bir çeşitle melezleyip tohum almak'], 'Eşeysiz çoğaltma genotipi olduğu gibi korur; tohumla çoğaltmada heterozigot lokuslar açılım gösterir.'),
  ('Bir çaprazlamada döllerin %75\'i baskın fenotipli çıkmıştır. Hiçbir ek bilgi olmadan döllerin genotipleri hakkında hangisi söylenebilir?', 'Baskın fenotipli döllerin bir kısmı homozigot, bir kısmı heterozigottur', ['Bütün döller heterozigottur', 'Baskın fenotipli döllerin tümü homozigottur ve kendileştirilince saf döl verir', 'Çekinik döller heterozigottur'], '3 : 1 açılım Aa × Aa\'dan gelir; baskın fenotiplilerin 1/3\'ü AA, 2/3\'ü Aa\'dır.'),
  ('Aslanağzında çiçek rengi eksik baskın (kırmızı, pembe, beyaz), yaprak biçimi ise tam baskın bir genle belirleniyor ve genler bağımsız. İki gen için de heterozigot iki bitki çaprazlanırsa döllerde kaç farklı fenotip görülür?', '6', ['4', '9', '3'], 'Renk için 3 fenotip (1 : 2 : 1), yaprak için 2 fenotip (3 : 1) vardır; 3 × 2 = 6 fenotip oluşur.'),
  ('İki genin de eksik baskınlık gösterdiği ve genlerin bağımsız açıldığı AaBb × AaBb çaprazlamasında fenotip sayısı ile genotip sayısı için hangisi doğrudur?', 'İkisi de 9\'dur', ['Fenotip 4, genotip 9\'dur', 'Fenotip 6, genotip 9\'dur', 'Fenotip 9, genotip 16\'dır'], 'Eksik baskınlıkta her genotipin kendine özgü fenotipi olduğundan 3 × 3 = 9 genotip, 9 ayrı fenotip verir.'),
  ('Çiçek renginde eksik baskınlık gösteren akşamsefası (Mirabilis jalapa) bitkisinde pembe çiçekli bir bitkiden kendileştirme yoluyla neden saf döl pembe bir hat elde edilemez?', 'Pembe renk yalnızca heterozigot genotipte ortaya çıktığı için', ['Pembe alel kendileştirmede yok olduğu için', 'Pembe çiçekli bitkiler kendileştirildiğinde hiç tohum oluşturamadığı için', 'Pembe renk çevre koşullarına bağlı olduğu için'], 'Pembe bireyler KB genotiplidir; kendileştirildiklerinde döllerde 1 kırmızı : 2 pembe : 1 beyaz açılımı her kuşak yeniden ortaya çıkar.'),
  ('Eksik baskınlık gösteren bir çiçekte bir çaprazlamanın döllerinden yarısı kırmızı, yarısı pembe çiçekli çıkmıştır. Ebeveynlerin fenotipleri nedir?', 'Kırmızı ve pembe', ['Pembe ve pembe', 'Kırmızı ve beyaz', 'Pembe ve beyaz çiçekli'], 'Kırmızı (KK) × pembe (KB) döllerinin 1/2\'si KK kırmızı, 1/2\'si KB pembe olur.'),
  ('Bir proteinin iki aleli elektroforezde farklı hızlarda göç eden iki form oluşturuyor. Heterozigot bir bireyin örneğinde ne görülmesi beklenir?', 'Her iki homozigottaki bantların birlikte görülmesi', ['Yalnızca baskın alele ait tek bir bant görülmesi', 'İki bandın ortasında yeni tek bir bant görülmesi', 'İki alel birbirini baskıladığı için hiç bant oluşmaması'], 'Heterozigotta iki alel de ifade edildiğinden iki protein formu birlikte bulunur; bu moleküler düzeyde eş baskınlıktır.'),
  ('ABO kan grubu sistemi aynı anda hangi iki kalıtım özelliğini örnekler?', 'Çok alellilik ve eş baskınlık', ['Eksik baskınlık ve eşeye bağlılık', 'Epistasi ve poligenik kalıtım', 'Letal alel ve eksik penetrans'], 'Sistemde üç alel (I^A, I^B, i) vardır; I^A ile I^B heterozigotta birlikte ifade edilir, ikisi de i\'ye baskındır.'),
  ('Eksik baskınlık ve eş baskınlık gösteren iki ayrı özellikte heterozigotlar kendi aralarında çaprazlanıyor. Her iki durumda döllerin fenotip oranı için hangisi doğrudur?', 'İki durumda da 1 : 2 : 1\'dir', ['Eksik baskınlıkta 3 : 1, eş baskınlıkta 1 : 2 : 1\'dir', 'Eksik baskınlıkta 1 : 2 : 1, eş baskınlıkta 3 : 1\'dir', 'İki durumda da 3 : 1\'dir'], 'Her iki durumda da heterozigotun kendine özgü bir fenotipi vardır; bu yüzden fenotip oranı genotip oranına eşittir.'),
  ('Tavşanlarda kürk rengi alelleri arasındaki baskınlık sırası C (tam renkli) > c^ch (şinşila) > c^h (himalaya) > c (albino) şeklindedir. Genotipi c^ch c^h olan şinşila bir tavşan, c^h c genotipli himalaya bir tavşanla çiftleştiriliyor. Yavrularda beklenen fenotip oranı nedir?', '1 şinşila : 1 himalaya', ['3 şinşila : 1 himalaya', '1 şinşila : 2 himalaya : 1 albino', '1 şinşila : 1 albino'], 'Döller c^ch c^h, c^ch c (şinşila) ile c^h c^h, c^h c (himalaya) olur; oran 2 : 2, yani 1 : 1\'dir.'),
  ('Tavşanlarda C (tam renkli) > c^ch (şinşila) > c^h (himalaya) > c (albino) baskınlık sırası geçerlidir. Tam renkli bir tavşan albino bir tavşanla çiftleştiğinde yavruların yarısı tam renkli, yarısı şinşila çıkıyor. Tam renkli ebeveynin genotipi nedir?', 'C c^ch', ['C c', 'Homozigot tam renkli', 'C c^h'], 'Albino ebeveyn yalnız c verdiğinden yavruların fenotipi öteki ebeveynin alelini gösterir; tam renkli ve şinşila yavrular C ve c^ch alellerinden gelir.'),
  ('Tavşanlarda C > c^ch > c^h > c baskınlık sırası geçerlidir. Aşağıdaki çiftleşmelerden hangisinde albino yavru doğması olanaksızdır?', 'C c^ch × c^h c', ['C c × c^ch c', 'c^h c × c^h c', 'c^ch c × c c'], 'Albino yavru (cc) için iki ebeveynin de c taşıması gerekir; C c^ch genotipli tavşan c taşımadığından bu çiftleşmeden albino doğamaz.'),
  ('Bir bitkide kendine uyuşmazlığı belirleyen S geninin popülasyonda düzinelerce aleli bulunabilir. Aynı popülasyondaki iki bitki için hangisi kesinlikle doğrudur?', 'Her biri en fazla iki farklı S aleli taşır', ['İkisi de bütün S alellerini taşır', 'İkisi de tek bir S aleli taşır', 'Biri çok sayıda, diğeri yalnızca bir S aleli taşır'], 'Alel sayısı popülasyon düzeyinde fazladır; diploit her birey bunlardan en çok iki tanesini taşır.'),
  ('Eksik baskınlığı karışarak kalıtımdan ayırt etmek için F1 pembe bitkileri kendi aralarında çaprazlayan bir araştırmacının elde ettiği hangi sonuç karışarak kalıtım görüşünü çürütür?', 'F2\'de kırmızı ve beyaz çiçeklerin yeniden ortaya çıkması', ['F2\'deki bütün bitkilerin pembe olması', 'F2\'de bütün çiçeklerin giderek daha açık bir pembe tona dönmesi', 'F1 bitkilerinin tohum vermemesi'], 'Kalıtım birimleri karışsaydı F2 hep pembe kalırdı; ebeveyn renklerinin yeniden görülmesi alellerin ayrı ve değişmeden aktarıldığını gösterir.'),
  ('ABO kan gruplarını 1901\'de keşfederek kan nakillerinin güvenli yapılmasının önünü açan bilim insanı kimdir?', 'Karl Landsteiner', ['Alexander Fleming', 'Robert Koch', 'Paul Ehrlich'], 'Landsteiner, farklı kişilerin kanlarının karıştırıldığında çökelme göstermesini inceleyerek ABO gruplarını tanımlamış ve 1930 Nobel ödülünü almıştır.'),
  ('AB kan gruplu bir anne ile genotipi I^A i olan A kan gruplu bir babanın çocuğunun B kan grubundan olma olasılığı nedir?', '1/4', ['1/2', 'Sıfır', '3/4'], 'B grubu için çocuk anneden I^B (1/2), babadan i (1/2) almalıdır: 1/2 × 1/2 = 1/4.'),
  ('A kan gruplu bir annenin çocuğu AB kan grubundandır. Babanın kan grubu aşağıdakilerden hangisi olabilir?', 'B ya da AB', ['A ya da AB', 'Yalnızca 0', 'A ya da 0'], 'Çocuktaki I^B aleli babadan gelmek zorundadır; I^B taşıyan babalar B ya da AB grubundandır.'),
  ('Bir babalık davasında yalnız ABO ve Rh kan gruplarına bakılıyor ve erkeğin kan grubu çocuğunkiyle uyumlu çıkıyor. Bu sonuç için en doğru değerlendirme hangisidir?', 'Erkeğin baba olabileceğini gösterir ama babalığı kanıtlamaz', ['Erkeğin kesinlikle baba olduğunu kanıtlar', 'Erkeğin baba olmadığını kesin olarak gösterir', 'Kan grupları kalıtımla ilgili olmadığı için hiçbir anlam taşımaz'], 'Kan grupları belirli kişileri dışlayabilir; ancak aynı kan grubundan çok sayıda insan bulunduğu için uyum babalığı kanıtlamaz.'),
  ('Bir hastanede iki bebek karışmıştır. Birinci aile A Rh− ve 0 Rh− kan gruplu, ikinci aile B Rh+ ve AB Rh+ kan gruplu ebeveynlerden oluşuyor. Bebeklerden biri A Rh−, diğeri B Rh+\'dır. Hangi eşleştirme kesindir?', 'B Rh+ bebek ikinci aileye aittir', ['A Rh− bebek ikinci aileye aittir', 'B Rh+ bebek birinci aileye aittir', 'İki bebek de aynı aileye aittir'], 'Birinci ailede iki ebeveyn de Rh− olduğu için Rh+ çocuk ve I^B aleli olmadığı için B grubu çocuk olamaz; B Rh+ bebek ikinci ailenindir.'),
  ('Genotipleri I^A i Rr ve I^B i Rr olan iki ebeveynin (Rh+ baskın, genler bağımsız) çocuğunun 0 Rh− kan grubundan olma olasılığı nedir?', '1/16', ['1/4', '1/8', '3/16'], '0 grubu (ii) olasılığı 1/4, Rh− (rr) olasılığı 1/4\'tür; 1/4 × 1/4 = 1/16.'),
  ('İki Rh+ ebeveynin Rh− bir çocuğu doğmuştur. Bu ailenin bir sonraki çocuğunun Rh− olma olasılığı nedir?', '1/4', ['1/2', '3/4', '1/8'], 'Rh− çocuk, iki ebeveynin de heterozigot olduğunu gösterir; Rr × Rr\'de rr olasılığı 1/4\'tür.'),
  ('Rh uyuşmazlığı ancak Rh− bir annenin Rh+ bir bebek taşımasıyla ortaya çıkabilir. Aşağıdaki çiftlerden hangisinin bebeklerinde Rh uyuşmazlığı riski hiç yoktur?', 'Anne Rh−, baba Rh−', ['Anne Rh−, baba Rh+ ve homozigot', 'Anne Rh−, baba Rh+ ve heterozigot', 'Anne Rh−, babanın Rh grubu bilinmiyor'], 'İki ebeveyn de rr olduğunda bütün bebekler Rh− olur; anne ile bebek arasında Rh uyuşmazlığı oluşamaz.'),
  ('Aynı anda doğmuş iki kardeşten biri A, diğeri B kan grubundandır. Bu bilgiden ikizlerle ilgili hangi sonuç çıkarılır?', 'Tek yumurta ikizi olamazlar', ['Kesinlikle aynı cinsiyettedirler', 'Ebeveynlerden biri AB grubundan olmalıdır', 'Tek yumurta ikizi olmalıdırlar'], 'Tek yumurta ikizleri aynı zigottan geldiği için aynı kan grubu genotipine sahiptir; farklı kan grubu çift yumurta ikizi olduklarını gösterir.'),
  ('Heterozigot A kan gruplu bir çiftin ilk iki doğumunda arka arkaya 0 gruplu bebek dünyaya gelmesi olasılığı kaçtır?', '1/16', ['1/4', '1/8', '1/2'], 'Her çocuk için ii olasılığı 1/4\'tür; iki bağımsız doğum için 1/4 × 1/4 = 1/16.'),
  ('0 kan gruplu bir kadın AB kan gruplu bir erkekle evleniyor. Çocuklarının kan grubu ile ilgili hangisi doğrudur?', 'Yalnız A ya da B olur', ['Yarısı 0, yarısı AB olur', 'Tamamı AB olur', 'A, B, AB ve 0 olabilir'], 'ii × I^A I^B çaprazlamasında döller I^A i (A) ya da I^B i (B) olur; ne 0 ne de AB doğar.'),
  ('B kan gruplu bir kadının annesi AB, babası 0 kan grubundandır. Bu kadın 0 kan gruplu bir erkekle evlenirse çocuklarının B grubundan olma olasılığı nedir?', '1/2', ['1/4', '3/4', '1'], 'Kadın babasından i almıştır, genotipi I^B i\'dir; I^B i × ii döllerinin yarısı B, yarısı 0 olur.'),
  ('A Rh+ bir kadın (I^A i, Rr) ile 0 Rh− bir erkeğin çocuklarında kaç farklı kan grubu fenotipi (ABO ve Rh birlikte) görülebilir?', '4', ['2', '6', '8'], 'ABO için A ve 0, Rh için + ve − olmak üzere 2 × 2 = 4 fenotip (A Rh+, A Rh−, 0 Rh+, 0 Rh−) çıkabilir.'),
  ('Annesi albino olan, kendisi normal pigmentli bir erkeğin albinizm aleli için taşıyıcı olma olasılığı nedir?', '1 (kesinlikle taşıyıcıdır)', ['1/2', '2/3', '1/4 (annesi hasta olduğu için)'], 'Albino anne yalnız a aleli verebildiği için erkek a alelini kesin almıştır; fenotipi normal olduğundan genotipi Aa\'dır.'),
  ('Birinci dereceden kuzenler, genomlarının ortalama olarak ne kadarını ortak ataları (büyükanne ve büyükbaba) aracılığıyla aynı kaynaktan almış olarak paylaşır?', '1/8', ['1/2', '1/4', '1/16'], 'Kardeşler genlerinin 1/2\'sini, yeğen ile amca 1/4\'ünü, birinci dereceden kuzenler ise 1/8\'ini ortak atalarından paylaşır; bu oran akraba evliliğinde çekinik hastalık riskini artırır.'),
  ('Bir soyağacında iki bireyi birbirine bağlayan çift yatay çizgi neyi ifade eder?', 'Akraba evliliğini', ['Boşanmış çifti', 'Tek yumurta ikizlerini', 'Evlat edinilmiş çocuğu'], 'Soyağacında eşler tek yatay çizgiyle bağlanır; aralarında kan bağı olan eşlerin evliliği çift çizgiyle gösterilir.'),
  ('Bir soyağacında özellik yalnız erkeklerde görülüyor, bu erkeklerin anneleri sağlıklı oluyor ve hasta erkeklerin oğullarına hiç geçmiyor. Bu örüntü en iyi hangi kalıtım biçimine uyar?', 'X\'e bağlı çekinik', ['Otozomal baskın', 'Y\'ye bağlı', 'X\'e bağlı baskın kalıtım'], 'Sağlıklı taşıyıcı annelerden oğullara geçmesi ve babadan oğula geçmemesi X\'e bağlı çekinik kalıtımın tipik özelliğidir; Y\'ye bağlı olsaydı babadan oğula geçerdi.'),
  ('Sağlıklı anne ve babası birinci dereceden kuzen olan bir çocukta nadir görülen bir hastalık ortaya çıkmıştır. Bu bulgu hastalığın kalıtımı için en çok hangisini düşündürür?', 'Otozomal çekinik kalıtım', ['Otozomal baskın ve tam penetranslı kalıtım', 'Y\'ye bağlı kalıtım', 'Mitokondriyal kalıtım'], 'Sağlıklı ebeveynden hasta çocuk doğması çekinikliği, ebeveynlerin akraba olması da ortak atadan gelen aynı alelin iki kopyasının birleşmesini düşündürür.'),
  ('Tam penetranslı otozomal baskın bir hastalığın görüldüğü bir ailede sağlıklı bir birey, ailesinde hastalık bulunmayan biriyle evleniyor. Çocuklarının hasta olma olasılığı nedir?', 'Sıfır', ['1/2', '1/4', '1/8'], 'Tam penetranslı baskın hastalıkta sağlıklı birey aa\'dır; aa × aa çocukları hastalık aleli taşımaz.'),
  ('Uzun boy, uzun parmaklar, mercek kayması ve aort genişlemesiyle seyreden, fibrilin proteinindeki bozukluktan kaynaklanan otozomal baskın bağ dokusu hastalığı hangisidir?', 'Marfan sendromu', ['Turner sendromu', 'Kistik fibrozis', 'Fenilketonüri'], 'Marfan sendromu FBN1 genindeki baskın mutasyonlardan kaynaklanır ve birçok sistemi etkileyen pleiotropik bir hastalıktır.'),
  ('Fenilketonürili bir bebeğe erken dönemden başlayarak fenilalanin miktarı kısıtlanmış diyet uygulanınca belirtilerin büyük ölçüde önlenmesi kalıtımla ilgili hangi ilkeyi gösterir?', 'Genotip aynı kalsa da çevrenin fenotipi değiştirebileceğini', ['Diyetin hastalık alelini zamanla sağlıklı alele dönüştürebildiğini', 'Hastalığın aslında kalıtsal olmadığını', 'Diyetle bebeğin taşıyıcı hâle geldiğini'], 'Diyet genleri değiştirmez; bozuk enzimin işleyemediği maddenin alınmasını azaltarak hastalığın fenotipte ortaya çıkmasını önler.'),
  ('Tay-Sachs hastalığında sinir hücrelerinde yağ türevi maddelerin birikmesinin temel nedeni nedir?', 'Bu maddeleri parçalayan bir lizozom enziminin işlevsiz olması', ['Bu maddelerin besinlerle gereğinden fazla alınıp kanla nöronlara taşınması', 'Sinir hücrelerinin bölünmesinin durması', 'Kanda glikoz düzeyinin düşmesi'], 'Tay-Sachs\'ta heksozaminidaz A enzimi çalışmadığından GM2 gangliozitler parçalanamaz ve nöronlarda birikir.'),
  ('Galaktozemili bebeklerde süt ve süt ürünleri tüketildiğinde karaciğer hasarı ve katarakt gelişir. Bu hastalığın kalıtım biçimi ve temel sorunu hangi seçenekte doğru verilmiştir?', 'Otozomal çekinik; galaktozun glikoza dönüştürülememesi', ['X\'e bağlı baskın; laktozun ince bağırsakta hiç sindirilememesi', 'Otozomal baskın; süt proteinine alerji', 'Y\'ye bağlı; kalsiyum emiliminin bozulması'], 'Galaktozemi otozomal çekinik bir enzim eksikliğidir; galaktoz metabolize edilemeyip birikir.'),
  ('Otozomal baskın bir hastalık için heterozigot bir erkek, sağlıklı bir kadınla evleniyor. Üç çocuklarının hiçbirinin hasta olmama olasılığı nedir?', '1/8', ['1/2', '3/8', '1/27'], 'Her çocuğun sağlıklı olma olasılığı 1/2\'dir; üç bağımsız doğum için (1/2)³ = 1/8.'),
  ('Neurofibromatozis tip 1 gibi bazı baskın hastalıklarda aynı aileden hastaların bir kısmında yalnız deride açık kahverengi lekeler, bir kısmında ise çok sayıda sinir tümörü görülür. Bu durum hangi kavramla açıklanır?', 'Değişken ekspresivite', ['Eksik baskınlık', 'Eş baskınlık', 'Eşeye bağlı kalıtım'], 'Ekspresivite, aynı genotipi taşıyanlarda fenotipin şiddet ve biçim bakımından farklı düzeylerde ortaya çıkmasıdır.'),
  ('Renk körlüğü X\'e bağlı çekinik kalıtılır. Taşıyıcı bir kadın renk körü bir erkekle evleniyor. Doğacak çocuğun renk körü bir kız olma olasılığı nedir?', '1/4', ['1/2', '1/8', 'Sıfır'], 'Kız olma 1/2; kızın renk körü olması için anneden Xᵃ alması 1/2. Birlikte 1/2 × 1/2 = 1/4.'),
  ('Hemofili taşıyıcısı bir kadın sağlıklı bir erkekle evleniyor. Çocuklarının ne kadarının hemofili alelini taşıması (hasta ya da taşıyıcı olarak) beklenir?', 'Yarısının', ['Dörtte birinin', 'Dörtte üçünün', 'Tamamının'], 'Annenin X kromozomlarından biri hemofili alelini taşır ve her çocuğa 1/2 olasılıkla geçer; oğullarda hastalık, kızlarda taşıyıcılık oluşur.'),
  ('Renk körü bir erkeğin kızı normal görüşlü bir erkekle evleniyor. Bu kadının doğacak bir oğlunun renk körü olma olasılığı nedir?', '1/2', ['1/4', 'Sıfır', '1'], 'Kadın babasından renk körlüğü alelini almıştır ve kesin taşıyıcıdır; oğullarının yarısı bu aleli alır.'),
  ('Anne ve babası normal görüşlü olan bir erkek çocuk renk körüdür. Renk körlüğü aleli aşağıdaki büyük ebeveynlerden hangisinden gelmiş olamaz?', 'Babasının babası', ['Annesinin annesi', 'Annesinin babası', 'Annesinin erkek kardeşi'], 'Erkek çocuk X kromozomunu annesinden alır; annesi bu X\'i kendi annesinden ya da babasından almıştır. Babanın babası yalnız Y aktarır.'),
  ('Renk körü bir kadının babası için aşağıdakilerden hangisi kesin olarak söylenebilir?', 'Renk körüdür', ['Taşıyıcıdır ama renk körü değildir', 'Normal görüşlüdür', 'Annesinin taşıyıcı olmasına göre değişir'], 'Kadın iki Xᵃ taşır; bunlardan biri babasından gelmiştir. Babanın tek X\'i Xᵃ olduğundan baba renk körüdür.'),
  ('Hemofili hastası bir kız çocuğunun doğabilmesi için ebeveynlerin genotipleri için hangisi gereklidir?', 'Babanın hasta, annenin en az taşıyıcı olması', ['Annenin hasta, babanın ise sağlıklı ve taşıyıcı olmaması', 'Yalnızca annenin taşıyıcı olması', 'İki ebeveynin de sağlıklı olması'], 'Kızın iki Xʰ alması gerekir: biri babadan (baba hasta olmalı), biri anneden (anne taşıyıcı ya da hasta olmalı).'),
  ('X\'e bağlı baskın bir hastalık için heterozigot hasta bir kadın sağlıklı bir erkekle evleniyor. Çocukları için hangisi beklenir?', 'Kızların da oğulların da yarısı hasta olur', ['Kızların tamamı hasta, oğullar ise sağlıklı olur', 'Yalnız oğulların yarısı hasta olur', 'Çocukların tamamı hasta olur'], 'Hasta alel annenin X kromozomlarından birindedir ve cinsiyetten bağımsız olarak her çocuğa 1/2 olasılıkla geçer.'),
  ('X\'e bağlı baskın hastalıkların toplumda kadınlarda erkeklere göre daha sık görülmesinin nedeni nedir?', 'İki X taşıyan kadınların aleli alma şansının daha yüksek olması', ['Erkeklerde X kromozomunun etkisiz hâle getirilmesi', 'Hastalık alelinin Y kromozomunda da bulunması', 'Kadınlarda baskın alellerin hormonların etkisiyle daha güçlü ifade edilmesi'], 'İki X kromozomu taşıyan kadınların, baskın alelin bir kopyasını almaları için iki fırsatı vardır; erkeklerin yalnız bir X\'i vardır.'),
  ('Meyve sineğinde beyaz göz X\'e bağlı çekinik bir özelliktir. Beyaz gözlü bir dişi kırmızı gözlü bir erkekle çaprazlanırsa F1 için hangisi beklenir?', 'Dişilerin tamamı kırmızı, erkeklerin tamamı beyaz gözlü olur', ['Bütün döller kırmızı gözlü olur', 'Bütün döller beyaz gözlü olur', 'Dişilerin de erkeklerin de yarısı beyaz, yarısı kırmızı gözlü olur'], 'Dişiler babadan Xᴿ aldıkları için kırmızı; erkekler tek X\'lerini beyaz gözlü anneden aldıkları için beyaz gözlü olur (çapraz kalıtım).'),
  ('Kedilerde turuncu ve siyah tüy rengi X kromozomundaki bir genin iki aleliyle belirlenir. Kaplumbağa kabuğu desenli (heterozigot) bir dişi kedi siyah bir erkekle çiftleşirse erkek yavruların renkleri nasıl olur?', 'Yarısı turuncu, yarısı siyah', ['Tamamı kaplumbağa kabuğu desenli', 'Tamamı siyah', 'Tamamı turuncu'], 'Erkek yavrular tek X\'lerini anneden alır; annenin iki X\'inden biri turuncu, biri siyah alel taşıdığından oğulların yarısı turuncu, yarısı siyah olur.'),
  ('Klasik hemofili (hemofili A) hangi pıhtılaşma faktörünün eksikliğinden kaynaklanır?', 'Faktör VIII', ['Faktör IX', 'Faktör XII', 'Fibrinojen'], 'Hemofili A faktör VIII, hemofili B (Christmas hastalığı) ise faktör IX eksikliğidir; ikisi de X\'e bağlı çekinik kalıtılır.'),
  ('Hemofili taşıyıcısı bir kadın hemofili hastası bir erkekle evleniyor. İki oğullarının ikisinin de hemofili olma olasılığı nedir?', '1/4', ['1/2', '1/8', '1/16'], 'Oğulların durumu babadan bağımsızdır; her oğul anneden Xʰ\'yi 1/2 olasılıkla alır: 1/2 × 1/2 = 1/4.'),
  ('X\'e bağlı çekinik bir özellik için kadınlarda heterozigot taşıyıcılık mümkünken erkekler için neden \'taşıyıcı\' terimi kullanılmaz?', 'Erkeklerin tek X\'indeki alel her durumda fenotipte görünür', ['Erkeklerde X kromozomu bulunmadığı için', 'Erkekler bu alelleri döllerine hiç aktarmadığı için', 'Erkeklerde bu genlerin bir kopyası da Y kromozomunda bulunduğu için'], 'Erkekler hemizigottur; çekinik alelin etkisini maskeleyecek ikinci bir alel bulunmadığından alel taşıyan erkek özelliği gösterir.'),
  ('X\'e bağlı baskın bir hastalık gösteren bir erkek sağlıklı bir kadınla evleniyor. Doğacak bir kızın hasta olma olasılığı ile bir oğlun hasta olma olasılığı sırasıyla nedir?', '1 ve 0', ['1/2 ve 1/2', '0 ve 1', '1/2 ve 0'], 'Baba X\'ini bütün kızlarına, Y\'sini bütün oğullarına verir; kızların tamamı hasta, oğulların hiçbiri hasta değildir.'),
  ('Hemofili hastası bir erkeğin sağlıklı oğlu, ailesinde hemofili bulunmayan ve taşıyıcı olmayan bir kadınla evleniyor. Bu çiftin çocuklarının hemofili olma olasılığı nedir?', 'Sıfır', ['1/4', '1/2', '1/8'], 'Oğul babasından Y aldığı için hemofili alelini taşımaz; eşi de taşımadığından çocuklara bu alel geçemez.'),
  ('Bir kadının iki oğlu Duchenne kas distrofisi hastasıdır; ailede başka hasta yoktur ve kadının kendisi sağlıklıdır. Bu kadın için en olası açıklama hangisidir?', 'Hastalık alelini X kromozomlarından birinde taşıyan bir taşıyıcıdır', ['Hastalık alelini Y kromozomunda taşır', 'Hastalık otozomal baskın olduğu için kendisi de belirti göstermeyen bir hastadır', 'Oğullarına alel babalarından geçmiştir'], 'Oğullar X\'lerini anneden alır; iki oğlun da hasta olması annenin taşıyıcı olduğunu kuvvetle düşündürür.'),
  ('Bal arılarında genotipi Aa olan bir kraliçe, a alelini taşıyan bir erkek arıyla çiftleşiyor. Kraliçenin yumurtladığı erkek yavruların genotipleri nasıl olur?', 'Yarısı A, yarısı a', ['Tamamı a', 'Tamamı Aa', 'Yarısı Aa, yarısı aa'], 'Erkek arılar döllenmemiş yumurtadan geliştiği için yalnız annenin alellerinden birini taşır; erkek arının sperminin bu yavrulara katkısı yoktur.'),
  ('Kuşlarda Z kromozomuna bağlı çekinik bir özelliğin hangi eşeyde daha sık görülmesi beklenir?', 'Dişilerde', ['Erkeklerde', 'İki eşeyde eşit sıklıkta', 'Yalnız kısır bireylerde'], 'Kuşlarda dişiler ZW\'dir ve tek Z taşıdıklarından çekinik alelin etkisi dişilerde doğrudan ortaya çıkar.'),
  ('Eşeyin etkilediği kalıtım ile eşeye sınırlı kalıtım arasındaki temel fark hangisidir?', 'Sınırlıda özellik tek eşeyde görülür; etkilenende iki eşeyde farklı sıklıkta görülür', ['Eşeye sınırlı genler X\'te, eşeyin etkilediği genler Y\'de bulunur', 'Eşeyin etkilediği kalıtımda genler yalnızca anneden aktarılır', 'İkisi arasında fark yoktur; aynı kavramın farklı kaynaklarda kullanılan iki adıdır'], 'Her ikisinde de genler genellikle otozomlardadır; eşeye sınırlı özellikler (ör. süt verimi) yalnız bir eşeyde ortaya çıkar, eşeyin etkilediği özellikler (ör. kellik) iki eşeyde farklı baskınlık gösterir.'),
  ('Tavuklarda tüy biçimini belirleyen bir gen için \'horoz tüyü\' fenotipi yalnız erkeklerde görülebilir; aynı genotipteki dişiler tavuk tüyü taşır. Bu durum hangi kalıtım tipine örnektir?', 'Eşeye sınırlı kalıtım', ['Z\'ye bağlı kalıtım', 'Eş baskınlık', 'Sitoplazmik (plastit) kalıtım'], 'Gen iki eşeyde de bulunduğu hâlde özellik yalnız bir eşeyde fenotipe yansıdığından bu eşeye sınırlı kalıtımdır.'),
  ('Yalnız Y kromozomu üzerinde bulunan ve babadan oğula aktarılan genlere ne ad verilir?', 'Holandrik genler', ['Otozomal genler', 'Hemizigot genler', 'Mitokondriyal genler'], 'Y\'ye bağlı genlere holandrik (yalnız erkeklerde bulunan) genler denir.'),
  ('İnsanda Y kromozomunun X kromozomuna göre çok daha az gen taşıması kalıtım örüntüleri bakımından hangi sonucu doğurur?', 'Y\'ye bağlı özelliklerin X\'e bağlılardan çok daha az olmasını', ['Erkeklerin kadınlardan daha az sayıda kalıtsal hastalık geçirmesini', 'Y\'nin anneden oğula aktarılmasını', 'Kadınların Y\'ye bağlı hastalıkları taşımasını'], 'X kromozomunda binden fazla gen varken Y\'de yalnız birkaç düzine gen vardır; bu yüzden bilinen Y\'ye bağlı özellik sayısı çok azdır.'),
  ('Kalıtsal kelliğin erkeklerde baskın, kadınlarda çekinik davranması hangi etkenle ilişkilendirilir?', 'Erkeklik hormonu testosteronun düzeyiyle', ['Genin Y kromozomunun eşleşmeyen bölgesinde bulunmasıyla', 'Genin X kromozomunda bulunmasıyla', 'Genin mitokondride bulunmasıyla'], 'Kellik geni otozomaldir; alelin etkisi yüksek testosteron düzeyinde baskın gibi, düşük düzeyde çekinik gibi ortaya çıkar.'),
  ('Kalıtsal kelliğin erkeklerde baskın, kadınlarda çekinik olduğu kabul ediliyor. Kel olmayan bir kadın ile kel bir erkeğin kel bir kızı doğuyor. Bu durumda ebeveynlerin genotipleri için hangisi doğrudur?', 'Annede ve babada en az birer kellik aleli bulunur', ['Annede kellik aleli yoktur', 'Babada kellik aleli yoktur', 'Kızın genotipi heterozigot, annesininki homozigottur'], 'Kadında kellik için iki alel (KK) gerekir; kız birini anneden, birini babadan almış olmalıdır.'),
  ('İnsanda eşey kromozomları bakımından erkekler, kuşlarda ise dişiler için kullanılan ve iki farklı eşey kromozomu taşımayı anlatan terim hangisidir?', 'Heterogametik', ['Homogametik', 'Hemizigot', 'Poliploit'], 'İki farklı eşey kromozomu taşıyan (XY ya da ZW) eşey, iki çeşit gamet ürettiği için heterogametik eşeydir.'),
  ('Kelebeklerde eşey ZW sistemiyle belirlenir. Bir kelebek popülasyonunda yumurtaların eşeyini belirleyen gamet hangisidir?', 'Dişinin yumurta hücresi', ['Erkeğin sperm hücresi', 'Hem sperm hem yumurta eşit ölçüde', 'Ortam sıcaklığı'], 'ZW sisteminde dişiler Z ya da W taşıyan iki tip yumurta, erkekler yalnız Z taşıyan sperm üretir; eşeyi yumurta belirler.'),
  ('A ve B genleri aynı kromozomda 20 harita birimi uzaklıktadır. Genotipi AB/ab (cis dizilim) olan bir bireyin oluşturduğu gametlerin yüzde kaçı Ab olur?', '%10', ['%20', '%40', '%25'], 'Rekombinant gametlerin toplamı %20\'dir ve iki rekombinant tipe (Ab, aB) eşit bölünür: her biri %10.'),
  ('A ve B genleri arasında rekombinasyon sıklığı %20\'dir. Genotipi Ab/aB (trans dizilim) olan bir bireyin oluşturduğu gametlerin yüzde kaçı AB olur?', '%10', ['%40', '%20', '%50'], 'Trans dizilimde AB bir rekombinant gamettir; %20\'lik rekombinant payının yarısı, yani %10\'u AB\'dir.'),
  ('Aralarında hiç krossing-over olmayan tam bağlı iki gen için AB/ab genotipli bir birey ab/ab ile test çaprazlamasına sokulursa döllerde ne beklenir?', 'Yalnız iki fenotip sınıfı, 1 : 1 oranında', ['Dört fenotip sınıfı, 1 : 1 : 1 : 1 oranında', 'Dört fenotip sınıfı, 9 : 3 : 3 : 1 oranında', 'Yalnız tek bir fenotip sınıfı'], 'Tam bağlılıkta yalnız AB ve ab gametleri oluşur; döller AaBb ve aabb olmak üzere iki sınıfa eşit dağılır.'),
  ('Bir bölgede bir krossing-over oluştuğunda hemen yakınında ikinci bir krossing-over oluşma olasılığının azalmasına ne ad verilir?', 'Girişim (interferans)', ['Epistasi', 'Penetrans', 'Komplementasyon (tamamlama)'], 'Girişim, bir krossing-overın komşu bölgedeki krossing-overları baskılamasıdır; gözlenen çift krossing-overlar beklenenden az olur.'),
  ('Meyve sineğinde 2n = 8\'dir. Bu türde kaç bağlantı grubu (birlikte kalıtılan gen grubu) bulunur?', '4', ['8', '2', '16'], 'Her kromozom çifti bir bağlantı grubu oluşturur; bağlantı grubu sayısı haploit kromozom sayısına (n = 4) eşittir.'),
  ('A ve B genleri arasında rekombinasyon %30\'dur. AB/ab genotipli bir bireyin gametlerinden AB tipinin oranı nedir?', '%35', ['%30', '%15', '%70'], 'Ebeveyn tipi gametler toplam %70\'tir ve AB ile ab arasında eşit bölünür: her biri %35.'),
  ('Bağlı genlerin zaman zaman birbirinden ayrılmasını homolog kromozomlar arasında parça değişimiyle açıklayan ve bu düşünceyle \'krossing-over\' kavramını meyve sineği deneylerine dayandıran bilim insanı kimdir?', 'Thomas Hunt Morgan', ['Gregor Johann Mendel', 'Hugo de Vries', 'Barbara McClintock'], 'Morgan 1911\'de bağlı genlerin yeniden birleşmesini kromozomlar arası değiş tokuşla açıklamış, öğrencisi Sturtevant da bunu harita için kullanmıştır.'),
  ('İki genin aynı kromozomda bulunduğu hâlde test çaprazlamasında bağımsız açılıyormuş gibi 1 : 1 : 1 : 1 oranı vermesi nasıl açıklanır?', 'Genlerin birbirinden çok uzak olması', ['Genlerin aynı lokusta bulunup alel gibi davranması', 'Genlerden birinin letal olması', 'Genlerin tam bağlı olması'], 'Çok uzak genler arasında hemen her mayozda krossing-over olduğundan rekombinasyon %50\'ye yaklaşır ve genler bağımsız gibi görünür.'),
  ('Genleri A–B–C sırasıyla dizilmiş ABC/abc genotipli bir dişi abc/abc ile çaprazlanıyor. Döllerin taşıdığı anneden gelen kromozomlar şunlardır: (I) ABc, (II) AbC, (III) Abc, (IV) ABC. Bunlardan hangisi çift krossing-over ürünüdür?', 'II', ['I', 'III', 'IV'], 'Çift krossing-overda uçtaki genler (A ve C) ebeveyn düzeninde kalır, yalnız ortadaki gen yer değiştirir: AbC ve aBc.'),
  ('Tavuklarda ibik biçimi iki genle belirlenir: R_pp gül, rrP_ bezelye, R_P_ ceviz, rrpp tek ibik verir. Saf döl gül ibikli ve saf döl bezelye ibikli tavuklar çaprazlanırsa F1\'in ibik biçimi ne olur?', 'Ceviz ibik', ['Gül ibik', 'Bezelye ibik', 'Tek ibik'], 'RRpp × rrPP çaprazlamasında F1 RrPp olur; iki baskın alelin birlikte bulunması ceviz ibik oluşturur.'),
  ('Tavuklarda R_P_ ceviz, R_pp gül, rrP_ bezelye ve rrpp tek ibik verir. Ceviz ibikli RrPp bir horoz tek ibikli bir tavukla çiftleştirilirse civcivlerde ibik biçimlerinin oranı nasıl olur?', '1 ceviz : 1 gül : 1 bezelye : 1 tek', ['9 ceviz : 3 gül : 3 bezelye : 1 tek', '3 ceviz : 1 tek ibik', 'Tamamı ceviz ibikli olur'], 'Bu bir test çaprazlamasıdır; RrPp\'nin dört gamet çeşidi eşit oranda olduğundan dört ibik biçimi 1 : 1 : 1 : 1 görülür.'),
  ('Etkisi, başka bir lokustaki genin epistatik etkisiyle maskelenen gene ne ad verilir?', 'Hipostatik gen', ['Baskın gen', 'Letal gen', 'Pleiotropik gen'], 'Maskeleyen gen epistatik, etkisi maskelenen gen ise hipostatiktir.'),
  ('Baskınlık ile epistasi arasındaki temel fark nedir?', 'Baskınlık bir genin alelleri, epistasi farklı genler arasındadır', ['Baskınlık yalnız bitkilerde, epistasi yalnız hayvanlarda görülür', 'Epistasi aynı genin alelleri arasında, baskınlık farklı genler arasında görülür', 'Baskınlık çevreyle, epistasi yalnız kromozom sayısıyla ilgilidir'], 'Baskınlık bir lokustaki iki alelin ilişkisidir; epistasi ise bir lokusun başka bir lokusun fenotipe yansımasını engellemesidir.'),
  ('İki beyaz çiçekli saf hattın melezlenmesiyle elde edilen F1\'in kendileştirilmesinden 182 mor ve 138 beyaz çiçekli F2 bitkisi sayılıyor. Bu sonuç en iyi hangi orana uyar?', '9 : 7', ['3 : 1', '1 : 1', '15 : 1'], 'Toplam 320 bitkide 9 : 7 oranı 180 : 140 bekletir; gözlenen 182 : 138 bu beklentiye çok yakındır.'),
  ('İki farklı genin ürünlerinin bir özelliğin ortaya çıkması için birlikte gerekli olduğu durumda (iki gende de en az bir baskın alel gerekmesi) dihibrit F2\'de hangi oran görülür?', '9 : 7', ['15 : 1', '12 : 3 : 1', '9 : 3 : 4'], 'İki gende de baskın alel bulunan A_B_ bireyler (9/16) özelliği gösterir; tek ya da iki genin çekinik homozigot olduğu bütün genotipler (7/16) göstermez.'),
  ('Bir özelliğin tek bir genle mi yoksa iki etkileşen genle mi belirlendiğini anlamak için dihibrit F2 sonuçlarının hangi özelliği en çok ipucu verir?', 'Fenotip oranlarının 16 paylı bir dağılıma uyup uymaması', ['F1 bireylerinin tümünün aynı boyda ve aynı renkte olması', 'Ebeveynlerin yaşları', 'Çaprazlamanın yapıldığı mevsim'], '9 : 7, 12 : 3 : 1, 15 : 1 gibi 16 paylı oranlar iki bağımsız genin etkileştiğini; 3 : 1 gibi 4 paylı oranlar tek geni düşündürür.'),
  ('Farelerde aguti renk için A_C_, siyah için aaC_ gerekir; cc albino verir. İki aguti fare (AaCc × AaCc) çiftleştirildiğinde yavruların kaçta kaçının albino olması beklenir?', '4/16', ['1/16', '3/16', '12/16'], 'cc genotipi A lokusundan bağımsız olarak albinizm verir; cc olasılığı 1/4 = 4/16\'dır.'),
  ('Boyun eklemeli üç gen çiftiyle belirlendiği bir modelde aabbcc bireyler 150 cm, AABBCC bireyler 180 cm boyundadır ve her eklemeli alel boyu eşit miktarda artırır. AaBbCc genotipli bir bireyin beklenen boyu kaç cm\'dir?', '165', ['160', '170', '175'], 'Altı alelin her biri 30 / 6 = 5 cm ekler; AaBbCc üç eklemeli alel taşıdığından 150 + 15 = 165 cm olur.'),
  ('Deri renginin eklemeli genlerle belirlendiği bir modelde orta tonlu iki ebeveynin bazı çocuklarının her iki ebeveynden de daha koyu ya da daha açık tenli olabilmesi nasıl açıklanır?', 'Çocuğun aldığı eklemeli alel sayısının farklı olabilmesi', ['Çocukta yeni genlerin kendiliğinden oluşması', 'Ebeveynlerin genlerinin çocukta birbirine karışarak giderek seyrelmesi', 'Deri renginin hiç kalıtılmaması'], 'Heterozigot ebeveynler eklemeli ve eklemesiz alelleri farklı birleşimlerde aktarır; bazı çocuklar daha çok, bazıları daha az eklemeli alel toplar.'),
  ('Çok sayıda genin eklemeli etkisiyle belirlenen ve çevreden de etkilenen bir özelliğin büyük bir popülasyondaki dağılımı genellikle nasıl görünür?', 'Ortalamada yığılan çan biçimli sürekli bir dağılım', ['Birbirinden kesin çizgilerle ayrılan iki sınıf', 'Yalnız iki uç değerde toplanan bir dağılım', 'Bütün değerlerin eşit sıklıkta görüldüğü bir dağılım'], 'Ara genotipler en çok sayıda birleşimle oluştuğundan ortalama değerler en sık, uç değerler en seyrek görülür; çevre etkisi de sınıfları birleştirir.'),
  ('Pleiotropi ile poligenik kalıtım arasındaki fark hangi seçenekte doğru verilmiştir?', 'Pleiotropide tek gen çok özelliği, poligenikte çok gen tek özelliği etkiler', ['Pleiotropide çok gen tek özelliği, poligenik kalıtımda ise tek gen çok özelliği etkiler', 'İkisi de yalnız eşey kromozomlarındaki genlerle ilgilidir', 'Pleiotropi yalnız bitkilerde, poligenik kalıtım yalnız hayvanlarda görülür'], 'Pleiotropik bir gen birbirinden farklı birçok fenotipi etkiler; poligenik özellik ise birçok genin ortak etkisiyle belirlenir.'),
  ('Belirli bir sıcaklıkta yaşamaya izin veren ama daha yüksek sıcaklıkta taşıyıcısını öldüren mutasyonlara ne ad verilir?', 'Koşullu letal mutasyon', ['Baskın ve her koşulda letal mutasyon', 'Sessiz mutasyon', 'Eşeye bağlı mutasyon'], 'Koşullu letal mutasyonlar (ör. sıcaklığa duyarlı mutasyonlar) ancak belirli çevre koşullarında öldürücü etki gösterir.'),
  ('Penetransı %80 olan otozomal baskın bir hastalık için heterozigot bir birey sağlıklı (aa) biriyle evleniyor. Çocuklarının hastalık belirtisi gösterme olasılığı nedir?', '0,4', ['0,5', '0,8', '0,2'], 'Çocuğun aleli alma olasılığı 0,5; aleli alan çocukta hastalığın ortaya çıkma olasılığı 0,8\'dir: 0,5 × 0,8 = 0,4.'),
  ('Polidaktili baskın kalıtılır. Bir ailede fazla parmaklı bir dedenin oğlu normal parmaklıdır, ancak bu oğlun çocuklarından biri fazla parmaklı doğmuştur. Bu durumun en iyi açıklaması hangisidir?', 'Oğul aleli taşıdığı hâlde belirti göstermemiştir', ['Polidaktili aslında X\'e bağlı çekinik kalıtılır', 'Torunun fazla parmağı kesin olarak yeni bir mutasyondur', 'Oğul aleli taşımadığı için torundaki durum yalnızca çevresel etkenlerden kaynaklanmıştır'], 'Baskın alel taşıdığı hâlde fenotip göstermeyen bireyler soyağacında kuşak atlıyormuş gibi bir görüntü yaratır; bu eksik penetranstır.'),
  ('Penetrans ile ekspresivite arasındaki fark hangi seçenekte doğru verilmiştir?', 'Penetrans fenotipin görülme oranını, ekspresivite şiddetini anlatır', ['Penetrans çekinik, ekspresivite baskın alellerle ilgilidir', 'Penetrans yalnız bitkilerde, ekspresivite yalnız hayvanlarda kullanılır', 'Penetrans genin kromozomdaki yerini, ekspresivite büyüklüğünü anlatır'], 'Penetrans, genotipi taşıyanların yüzde kaçında fenotipin ortaya çıktığıdır; ekspresivite ise ortaya çıkan fenotipin şiddetidir.'),
  ('Huntington hastalığının belirtileri çoğunlukla 35–45 yaşlarından sonra ortaya çıkar. Hastalık alelini taşıyan 20 yaşındaki birinin henüz belirti göstermemesi hangi kavramla ilişkilidir?', 'Yaşa bağlı penetrans', ['Eş baskınlık', 'Pleiotropi', 'Eşeye sınırlı kalıtım'], 'Bazı genotiplerin fenotipe yansıması yaşa bağlıdır; aynı genotipteki bireylerde belirti olasılığı yaşla artar.'),
  ('Eklemeli genlerle belirlenen bir özellikte iki uç saf hattın F1\'i ara değer gösterir. Bu durum ilk bakışta hangi kalıtım tipiyle karıştırılabilir?', 'Eksik baskınlıkla', ['Eşeye bağlı kalıtımla', 'Letal alellerle', 'Mitokondriyal kalıtımla'], 'F1\'in ara fenotipi eksik baskınlığa benzer; F2\'de çok sayıda sınıf ortaya çıkması ise poligenik kalıtımı gösterir.'),
  ('Himalaya tavşanlarında kulak, burun, pati ve kuyruk uçları siyah, vücudun geri kalanı beyazdır. Sırtındaki tüyleri tıraş edilen bir tavşanın bu bölgesine tüyler yeniden çıkarken buz torbası uygulanırsa ne gözlenir?', 'O bölgede siyah tüyler çıkar', ['O bölgede beyaz tüyler çıkar', 'O bölgede hiç tüy çıkmaz', 'Tavşanın bütün tüyleri siyaha döner'], 'Pigment enzimi sıcaklığa duyarlıdır ve yalnız serin bölgelerde çalışır; soğutulan sırt derisinde de pigment üretilir.'),
  ('Himalaya tavşanlarındaki renk deseninin oluşmasının temel nedeni nedir?', 'Pigment enziminin yalnız serin bölgelerde etkin olması', ['Uç bölgelerdeki hücrelerin farklı genler taşıması', 'Uç bölgelerin daha çok güneş görmesi', 'Beyaz bölgelerde pigment genlerinin silinmiş olması'], 'Bütün hücreler aynı genotipe sahiptir; sıcaklığa duyarlı enzim vücudun serin uçlarında çalışır, sıcak gövdede çalışmaz.'),
  ('İki buğday çeşidinden A çeşidi kurak bölgelerde B\'den daha verimli olurken, sulak bölgelerde B çeşidi A\'dan daha verimli oluyor. Bu durum hangi kavramla en iyi açıklanır?', 'Genotip ile çevre arasındaki etkileşim', ['Eksik baskınlık', 'Bağlı genler', 'Pleiotropi'], 'Farklı genotiplerin çevre değişikliklerine verdiği tepkiler farklı olduğunda, hangi genotipin üstün olduğu çevreye göre değişebilir.'),
  ('Kalıtsal bir hastalığın belirtilerinin, genotipi normal bir bireyde çevresel bir etkenle (ör. gebelikte alınan bir ilaçla) aynen ortaya çıkmasına ne ad verilir?', 'Fenokopi', ['Penetrans', 'Mutasyon', 'Ekspresivite'], 'Fenokopi, çevresel etkiyle oluşan ve kalıtsal bir fenotipi taklit eden ama döllere aktarılmayan özelliktir.'),
  ('Bir ailenin bütün bireylerinin aynı dili konuşması ve aynı yemekleri sevmesi bu özelliklerin genetik olduğunu kanıtlar mı?', 'Hayır; aile bireyleri ortak çevreyi de paylaştığı için yalnız aile içi benzerlik kalıtımı kanıtlamaz', ['Evet; ailede görülen her özellik kalıtsaldır', 'Evet; ancak yalnızca anneden kalıtılır', 'Hayır; çünkü dil ve beslenme her kuşakta mutasyona uğrar'], 'Aile bireyleri hem genleri hem çevreyi paylaşır; bir özelliğin kalıtsal olduğunu göstermek için evlat edinme ya da ikiz çalışmaları gibi ayırt edici yöntemler gerekir.'),
  ('İkiz çalışmalarında bir özellik tek yumurta ikizlerinde çift yumurta ikizlerine göre çok daha sık birlikte görülüyor. Bu bulgu en çok neyi destekler?', 'Özelliğin oluşumunda kalıtımın önemli payı olduğunu', ['Özelliğin tamamen çevreyle ve beslenmeyle belirlendiğini', 'Özelliğin X\'e bağlı kalıtıldığını', 'Özelliğin yalnız anneden geçtiğini'], 'Tek yumurta ikizleri genetik olarak özdeştir; benzerliğin bu grupta belirgin yüksek olması genetik katkıya işaret eder.'),
  ('Bir özellik için yapılan resiprokal çaprazlamalarda (ebeveyn eşeyleri yer değiştirerek) F1 sonuçları birbirinden farklı çıkıyor. Bu durum en çok hangi kalıtım biçimlerinden birini düşündürür?', 'Eşey kromozomuna bağlı ya da sitoplazmik kalıtım', ['Otozomal tam baskın kalıtım', 'Otozomal eksik baskın ve tam penetranslı kalıtım', 'Otozomal eş baskın kalıtım'], 'Otozomal genlerde resiprokal çaprazlamalar aynı sonucu verir; sonucun ebeveynin eşeyine göre değişmesi genin eşey kromozomunda ya da sitoplazmada olduğunu düşündürür.'),
  ('Aynı fenotipi (ör. beyaz göz) gösteren iki çekinik mutant sinek çaprazlanıyor ve döllerin tamamı normal (yabanıl tip) fenotipte çıkıyor. Bu sonuçtan hangi çıkarım yapılır?', 'İki mutasyon farklı genlerdedir', ['İki mutasyon aynı gendedir', 'Mutasyonlar baskındır', 'Döllerin tamamı iki gen bakımından homozigottur'], 'Komplementasyon testinde yabanıl tip döl, her mutantın ötekinin eksik genini sağladığını, yani mutasyonların farklı genlerde olduğunu gösterir.'),
  ('İki çekinik mutant bitki çaprazlandığında döllerin tamamı yine mutant fenotipte çıkıyor. Bu sonuç mutasyonlar hakkında neyi gösterir?', 'İki mutasyonun aynı gende olduğunu', ['İki mutasyonun farklı kromozomlarda olduğunu', 'Mutasyonların birbirini tamamladığını', 'Mutasyonların baskın olduğunu'], 'Komplementasyon olmaması, döllerin aynı genin iki bozuk kopyasını taşıdığını, yani mutasyonların aynı gende olduğunu gösterir.'),
  ('Bir dihibrit F2 sonucunun 9 : 3 : 3 : 1 oranına uyup uymadığı ki-kare testiyle sınanacaktır. Bu testte serbestlik derecesi kaçtır?', '3', ['4', '1', '2'], 'Serbestlik derecesi, fenotip sınıfı sayısının bir eksiğidir: 4 − 1 = 3.'),
  ('Bir öğrenci 3 : 1 bekleyen çaprazlamasında 400 döl elde ediyor ve 300 baskın : 100 çekinik sayıyor. Ki-kare değeri kaç çıkar?', '0', ['1', '3,84', '100'], 'Gözlenen değerler beklenenlerle (300 ve 100) tam olarak aynı olduğundan her sınıf için (G − B)² / B = 0\'dır.'),
  ('Karışarak kalıtım görüşü doğru olsaydı, eşeyli üreyen bir popülasyondaki kalıtsal çeşitlilik kuşaklar boyunca nasıl değişirdi?', 'Her kuşak ortalamaya doğru giderek azalırdı', ['Her kuşak hızla artardı', 'Hiç değişmeden korunurdu', 'Yalnız erkeklerde artar, dişilerde ise azalırdı'], 'Özellikler karışsaydı her döl ebeveynlerin ortalamasını alır ve uç fenotipler kaybolurdu; Mendel\'in parçacıklı kalıtımında ise aleller değişmeden korunur.'),
  ('Mendel\'in deneylerini sayısal ve olasılığa dayalı bir yaklaşımla tasarlamasında, öğrenimini gördüğü hangi alanların etkisi olduğu kabul edilir?', 'Viyana\'da aldığı fizik ve matematik eğitiminin', ['Tıp fakültesinde aldığı cerrahi eğitiminin', 'Hukuk fakültesinde aldığı ceza ve medeni hukuk eğitiminin', 'Konservatuvarda aldığı müzik eğitiminin'], 'Mendel Viyana Üniversitesi\'nde Christian Doppler gibi hocalardan fizik ve matematik dersleri almış, deney tasarımı ve istatistiksel düşünceyi buradan edinmiştir.'),
  ('Mendel\'in 1868\'den sonra bilimsel çalışmalarını büyük ölçüde bırakmasının başlıca nedeni hangisidir?', 'Manastırın başrahibi seçilip yönetim işlerine yoğunlaşması', ['Deneylerde kullandığı bezelye tohumlarının bölgede bulunamaz hâle gelmesi', 'Üniversitede kürsü başkanı olması', 'Deneylerinin devlet tarafından yasaklanması'], 'Mendel 1868\'de Aziz Thomas Manastırı\'nın başrahibi oldu; yönetim ve vergi anlaşmazlıkları zamanının çoğunu aldı.'),
  ('Mendel\'in incelemek üzere seçtiği bezelye karakterlerinin ortak özelliği hangisidir?', 'Ara biçimi olmayan iki belirgin seçeneğe sahip olmaları', ['Tümünün çevreden güçlü biçimde etkilenmesi', 'Tümünün eklemeli etki gösteren çok sayıda genle belirlenmesi', 'Tümünün yalnız olgun bitkilerde ölçülebilmesi'], 'Sarı ya da yeşil, düz ya da buruşuk gibi açık seçenekler döllerin sınıflara ayrılıp sayılmasını kolaylaştırmıştır.'),
  ('Kalıtımda kromozomların rolünü ortaya koyan çalışmaları nedeniyle 1933 Nobel Fizyoloji veya Tıp Ödülü\'nü alan bilim insanı kimdir?', 'Thomas Hunt Morgan', ['William Bateson', 'Hugo de Vries', 'Archibald Edward Garrod'], 'Morgan meyve sineğindeki çalışmalarıyla genlerin kromozomlar üzerinde dizili olduğunu göstermiş ve 1933\'te Nobel ödülünü almıştır.'),
  ('İkiz çalışmalarını insan özelliklerinde kalıtım ve çevrenin payını araştırmak için ilk kullananlardan olan ve \'doğa ve yetiştirme\' (nature and nurture) ifadesini yaygınlaştıran bilim insanı kimdir?', 'Francis Galton', ['Gregor Mendel', 'Louis Pasteur', 'Alfred Russel Wallace'], 'Darwin\'in kuzeni Galton, 19. yüzyılda ikizleri inceleyerek kalıtım ve çevre etkisini ayırmaya çalışmıştır.'),
  ('Meyve sineği genetiğinde bir alelin yanına yazılan \'+\' işareti neyi gösterir?', 'O alelin yabanıl tip olduğunu', ['O alelin baskın letal olduğunu', 'O alelin X kromozomunda olduğunu', 'O alelin yeni oluşmuş bir mutasyon olduğunu'], 'Örneğin w beyaz göz mutant alelini, w⁺ ise kırmızı göz veren yabanıl tip alelini gösterir.'),
  ('Mendel\'in bulgularını yeniden keşfedenler arasında yer alan ve bezelye ile mısırda çalışan Alman botanikçi kimdir?', 'Carl Correns', ['Ernst Haeckel', 'Matthias Schleiden', 'Robert Koch'], 'Carl Correns, Hugo de Vries ve Erich von Tschermak ile birlikte 1900\'de Mendel\'in yasalarını bağımsız olarak yeniden keşfetmiştir.'),
  ('Köpeklerde alacalı \'merle\' deseni veren alel heterozigotlarda istenen deseni oluşturur; homozigotlarda ise sıklıkla körlük ve sağırlık görülür. Yetiştiricilerin iki merle köpeği birbiriyle çiftleştirmekten kaçınmasının nedeni nedir?', 'Yavruların dörtte birinin sorunlu homozigot merle olacak olması', ['Merle alelinin bu çiftleşmede kaybolacak olması', 'Bütün yavruların kısır doğacak olması', 'Yavruların tümünün merle desenini kaybedip düz renkli doğacak olması'], 'Mm × Mm çiftleşmesinde yavruların 1/4\'ü MM olur; bu yavrularda alelin pleiotropik etkileri (göz ve kulak sorunları) ortaya çıkar.'),
  ('Mor (baskın) ve sarı (çekinik) taneler için heterozigot iki mısır bitkisinin çaprazlanmasından oluşan tek bir koçanda yaklaşık 3 mor : 1 sarı tane oranı görülebilir. Bunun nedeni nedir?', 'Koçandaki her tanenin ayrı bir döl olması', ['Koçanın tek bir dölü temsil etmesi', 'Tanelerin rengini yalnız anne bitkinin genotipinin belirlemesi', 'Sarı tanelerin mutasyonla oluşması'], 'Her mısır tanesi ayrı bir polen tanesiyle döllenmiş bir yumurtadan gelişir; bu yüzden bir koçan çok sayıda dölü bir arada gösterir.'),
  ('Kır (gri) at alelini taşıyan taylar genellikle koyu renkli doğar ve yıllar içinde giderek ağarır. Bu gözlem fenotiple ilgili hangi ilkeyi gösterir?', 'Bir genin etkisinin yaşla ortaya çıkabileceğini', ['Tüy renginin hiç kalıtılmadığını', 'Atlarda renk genlerinin DNA dizisinin yaşla birlikte değiştiğini', 'Gri rengin çekinik olduğunu'], 'Genotip doğumdan itibaren aynıdır; gri alelin fenotipe etkisi yaş ilerledikçe belirginleşir.'),
  ('Üç çocuklu bir ailede çocuklar arasında en az bir kız ve en az bir erkek bulunma olasılığı nedir?', '3/4', ['1/2', '7/8', '3/16'], 'Bütün çocukların aynı cinsiyette olma olasılığı 1/8 + 1/8 = 1/4\'tür; tümleyeni 1 − 1/4 = 3/4.'),
  ('Beş çocuklu bir ailede çocukların hepsinin aynı cinsiyetten olma olasılığı nedir?', '1/16', ['1/32', '1/5', '1/10'], 'Tamamının kız olma olasılığı 1/32, tamamının erkek olma olasılığı 1/32\'dir; toplam 2/32 = 1/16.'),
  ('Otozomal baskın bir hastalık için heterozigot bir anne ile sağlıklı bir babanın üç çocuğundan en az birinin hasta olma olasılığı nedir?', '7/8', ['1/2', '3/4', '1/16'], 'Hiçbir çocuğun hasta olmaması (1/2)³ = 1/8\'dir; en az birinin hasta olması 1 − 1/8 = 7/8.'),
  ('Taşıyıcı iki ebeveynin (Aa × Aa) iki çocuğundan birinin otozomal çekinik hastalık göstermesi, diğerinin sağlıklı olması olasılığı (sıra önemsiz) nedir?', '3/8', ['3/16', '1/4', '9/16'], 'Hasta–sağlıklı ve sağlıklı–hasta olmak üzere iki sıra vardır: 2 × 1/4 × 3/4 = 6/16 = 3/8.'),
  ('Genetik danışmanlıkta bir çifte \'her gebelikte riskiniz 1/4\' denmesi aşağıdakilerden hangisi anlamına gelir?', 'Her çocuk için, öncekilerden bağımsız olarak risk 1/4\'tür', ['Dört çocuktan tam olarak biri kesin hasta olacaktır', 'İlk üç çocuk sağlıklıysa dördüncüsü kesin hastadır', 'Bir hasta çocuk doğduktan sonra risk sıfırlanır'], 'Her döllenme bağımsız bir olaydır; 1/4 uzun vadeli bir olasılıktır ve dört çocuktan birinin hasta olacağını garanti etmez.'),
  ('Bir ailede AaBbCc × aaBbcc çaprazlaması yapılıyor (genler bağımsız, baskınlık tam). Döllerin kaçta kaçı üç karakterde de çekinik fenotip gösterir?', '1/16', ['1/64', '1/8', '3/32'], 'aa: 1/2, bb: 1/4, cc: 1/2; çarpım 1/2 × 1/4 × 1/2 = 1/16.'),
  ('AaBbCcDd genotipli bir birey aabbccdd ile çaprazlanıyor (genler bağımsız). Döllerin kaçta kaçı test edilen bireyle aynı genotipe (AaBbCcDd) sahip olur?', '1/16', ['1/4', '1/8', '1/256'], 'aabbccdd yalnız abcd gameti verir; dölün AaBbCcDd olması için öteki ebeveynden ABCD gameti gelmeli: (1/2)⁴ = 1/16.'),
  ('Sağlıklı bir çiftin ilk çocuğu otozomal çekinik bir hastalıkla doğmuştur. Bu çiftin sonraki iki çocuğunun ikisinin de sağlıklı olma olasılığı nedir?', '9/16', ['1/16', '3/4', '1/2'], 'Hasta çocuk ebeveynlerin Aa × Aa olduğunu gösterir; her çocuğun sağlıklı olma olasılığı 3/4\'tür: 3/4 × 3/4 = 9/16.'),
  ('Bir soyağacında hasta bir kızın babasının sağlıklı olduğu görülüyor. Bu bilgi tek başına hangi kalıtım tipini kesin olarak dışlar?', 'X\'e bağlı çekinik', ['Otozomal çekinik', 'Otozomal baskın', 'X\'e bağlı baskın kalıtım'], 'X\'e bağlı çekinik bir özellik için kızın iki Xᵃ taşıması gerekir; babadan gelen X de Xᵃ olacağından baba hasta olmalıdır.'),
  ('Sağlıklı bir anne ve babanın hasta bir oğlu bulunan bir soyağacında, yalnız bu bilgiye dayanarak hangi kalıtım biçimleri olası kabul edilir?', 'Otozomal çekinik ya da X\'e bağlı çekinik', ['Yalnız otozomal baskın, tam penetranslı kalıtım', 'Otozomal baskın ya da X\'e bağlı baskın', 'Yalnız Y\'ye bağlı'], 'Sağlıklı ebeveynden hasta çocuk doğması çekinikliği gösterir; çocuk erkek olduğu için alel otozomal olabileceği gibi taşıyıcı anneden gelen X\'te de olabilir.'),
  ('Bir soyağacında baba hasta, anne sağlıklı; kızları hasta, oğulları sağlıklıdır. Aşağıdaki kalıtım biçimlerinden hangisi bu aile için kesinlikle olanaksızdır?', 'Y\'ye bağlı kalıtım', ['Otozomal baskın kalıtım', 'X\'e bağlı baskın kalıtım', 'Otozomal çekinik kalıtım'], 'Y\'ye bağlı bir özellik babadan bütün oğullara geçer ve kızlarda hiç görülmez; burada tam tersi bir durum vardır.'),
  ('Nadir görülen çekinik bir hastalığın soyağacı problemlerinde, aileye evlilik yoluyla katılan ve ailesinde hastalık bulunmayan bireyler için genellikle hangi varsayım yapılır?', 'Alel taşımayan homozigot oldukları', ['Taşıyıcı oldukları', 'Hasta oldukları', 'Genotiplerinin hesaplanamayacağı'], 'Alel toplumda çok seyrek olduğundan, aksine bir bilgi yoksa aileye dışarıdan gelen bireylerin taşıyıcı olmadığı kabul edilir.'),
  ('Nadir görülen otozomal baskın bir hastalığın soyağacı problemlerinde hasta bireylerin genotipi için genellikle hangi varsayım yapılır?', 'Heterozigot oldukları', ['Homozigot baskın oldukları', 'Homozigot çekinik oldukları', 'Hemizigot oldukları'], 'Nadir bir alelin iki kopyasını birden almak çok düşük olasılıklıdır; bu yüzden hastalar genellikle Aa kabul edilir.'),
  ('Soyağacı çalışmalarında ailenin incelenmesine yol açan, tıbbi dikkati ilk çeken bireye ne ad verilir?', 'Proband (indeks olgu)', ['Taşıyıcı', 'Kurucu birey', 'Akraba (birinci derece kuzen)'], 'Proband, soyağacının çıkarılmasına neden olan ilk tanı konmuş kişidir ve şemada genellikle bir okla gösterilir.'),
  ('İki aleli bulunan X\'e bağlı bir gen için bir popülasyonda (dişiler ve erkekler birlikte) kaç farklı genotip bulunabilir?', '5', ['3', '4', '6'], 'Dişilerde XᴬXᴬ, XᴬXᵃ, XᵃXᵃ (3); erkeklerde XᴬY, XᵃY (2) olmak üzere toplam 5 genotip vardır.'),
  ('Annesi taşıyıcı, babası sağlıklı olan bir erkeğin renk körlüğü bakımından sağlıklı olduğu biliniyor. Bu erkeğin kızlarının renk körlüğü alelini taşıma olasılığı nedir?', 'Sıfır', ['1/2', '1/4', '1'], 'Erkeğin sağlıklı olması tek X\'inin normal alel taşıdığını gösterir; kızlarına bu normal X\'i verir.'),
  ('X\'e bağlı çekinik bir hastalık için taşıyıcı olan ve sağlıklı bir erkekle evli bir kadının dört oğlunun hiçbirinin hasta olmama olasılığı nedir?', '1/16', ['1/4', '1/8', '1/2'], 'Her oğlun sağlıklı olma olasılığı 1/2\'dir; dört bağımsız doğum için (1/2)⁴ = 1/16.'),
  ('Hemofili alelini taşıdığı bilinmeyen bir kadının sağlıklı bir erkekten iki hemofili hastası oğlu doğuyor. Bu kadının bir kızının taşıyıcı olma olasılığı nedir?', '1/2', ['1/4', '1', 'Sıfır'], 'İki hasta oğul annenin taşıyıcı olduğunu gösterir; kızlar annenin iki X\'inden birini 1/2 olasılıkla alır.'),
  ('Bir ailede bir hastalık yalnız erkeklerde görülüyor; hasta erkeklerin bütün oğulları hasta, bütün kızları sağlıklı ve kızlarının çocuklarında da hastalık hiç görülmüyor. Bu durum hangi kalıtım tipine uyar?', 'Y\'ye bağlı kalıtım', ['X\'e bağlı çekinik kalıtım', 'Mitokondriyal kalıtım', 'Otozomal çekinik kalıtım'], 'Özelliğin yalnız babadan oğula geçmesi ve kızlar aracılığıyla hiç aktarılmaması Y\'ye bağlı kalıtımı gösterir; X\'e bağlı çekinikte kızların oğulları etkilenirdi.'),
  ('Soyağacında içi boş bir eşkenar dörtgen (baklava) simgesi neyi gösterir?', 'Cinsiyeti belirtilmemiş bireyi', ['Hasta kadını', 'Taşıyıcı erkeği', 'Düşükle sonuçlanmış bir gebeliği'], 'Standart soyağacı gösteriminde cinsiyeti bilinmeyen ya da belirtilmeyen bireyler eşkenar dörtgenle gösterilir.'),
  ('Duchenne kas distrofisinde kas liflerinin zamanla yıkılmasının nedeni, kas hücre zarını hücre iskeletine bağlayan hangi proteinin bulunmamasıdır?', 'Distrofin', ['Kolajen', 'Keratin', 'Miyozin hafif zinciri'], 'Distrofin geni X kromozomundadır; protein yokluğunda kasılma sırasında kas hücre zarı hasar görür ve lifler yıkılır.'),
  ('Albinizmin en yaygın biçiminde melanin sentezinin ilk basamaklarını yürüten hangi enzim işlevsizdir?', 'Tirozinaz', ['Amilaz', 'Laktaz', 'Karbonik anhidraz'], 'Tirozinaz, tirozin amino asidini melanine dönüştüren yolun anahtar enzimidir; geni bozuk olan homozigotlarda pigment üretilemez.'),
  ('Fenilketonüride fenilalaninin vücutta birikmesine yol açan enzim eksikliği hangisidir?', 'Fenilalanin hidroksilaz', ['Laktaz', 'Tirozinaz', 'Glukoz-6-fosfat dehidrogenaz'], 'Fenilalanin hidroksilaz fenilalanini tirozine dönüştürür; enzim çalışmadığında fenilalanin ve yan ürünleri birikerek sinir sistemine zarar verir.'),
  ('Aşağıdaki durumlardan hangisi tek bir genin Mendel kalıtımına uyan değil, birçok gen ve yaşam biçimi etkenlerinin birlikte belirlediği (çok etkenli) bir duruma örnektir?', 'Tip 2 diyabet', ['Fenilketonüri', 'Hemofili A', 'Huntington hastalığı'], 'Tip 2 diyabet riski birçok genin yanında beslenme, hareketsizlik ve kilo gibi çevresel etkenlerle belirlenir; diğerleri tek genli hastalıklardır.'),
  ('Bir ailede otozomal çekinik bir hastalık için büyükbaba taşıyıcıdır; ailenin geri kalan bireylerinin (dışarıdan evlenenler dâhil) taşıyıcı olmadığı varsayılıyor. Bu büyükbabanın torununun taşıyıcı olma olasılığı nedir?', '1/4', ['1/2', '1/8', '1/16'], 'Büyükbabanın çocuğu 1/2, o çocuğun çocuğu da 1/2 olasılıkla aleli alır: 1/2 × 1/2 = 1/4.'),
  ('Taşıyıcı iki ebeveynin (Aa × Aa) çocukları arasında otozomal çekinik hastalık gösteren ilk çocuğun ikinci çocuk olma olasılığı nedir?', '3/16', ['1/4', '1/16', '9/16'], 'Birinci çocuk sağlıklı (3/4), ikinci çocuk hasta (1/4) olmalıdır: 3/4 × 1/4 = 3/16.'),
  ('AABBCC ve aabbcc saf hatlarının melezlenmesiyle elde edilen F1\'in kendileştirilmesinden oluşan F2\'de (genler bağımsız) bireylerin kaçta kaçı üç gen bakımından da homozigottur?', '1/8', ['1/64', '1/27', '3/8'], 'Her lokusta homozigot olma (AA ya da aa) olasılığı 1/2\'dir; üç lokus için (1/2)³ = 1/8.'),
  ('AaBb × AaBb çaprazlamasından elde edilen F2\'de (genler bağımsız) her iki karakter için de saf döl verecek, yani iki lokusta da homozigot olan bireylerin oranı nedir?', '1/4', ['1/16', '1/9', '9/16'], 'Her lokusta homozigot olma olasılığı 1/2\'dir: 1/2 × 1/2 = 1/4 (AABB, AAbb, aaBB, aabb).'),
  ('Bir bireyin yalnız AbC ve Abc tipinde gamet ürettiği, bunların da eşit oranda olduğu belirleniyor (genler bağımsız). Bu bireyin genotipi nedir?', 'A ve b bakımından homozigot, yalnız C bakımından heterozigot', ['Üç gen bakımından da heterozigot', 'A ve C bakımından homozigot baskın, yalnız B bakımından heterozigot', 'A ve C bakımından heterozigot, B bakımından homozigot çekinik'], 'A ve b her gamette sabit olduğundan birey AA ve bb\'dir; C ile c eşit oranda bulunduğundan Cc\'dir.'),
  ('Çiçek renginde eksik baskınlık (kırmızı KK, pembe KB, beyaz BB), boyda tam baskınlık (uzun U, kısa u) gösteren bir bitkide KBUu × KBuu çaprazlamasından doğan bitkilerin kaçta kaçı pembe çiçekli ve uzun boylu olur?', '1/4', ['1/8', '3/8', '1/2'], 'Pembe olma (KB × KB) 1/2, uzun olma (Uu × uu) 1/2\'dir; 1/2 × 1/2 = 1/4.'),
  ('Monohibrit bir test çaprazlamasında 1 : 1 oranının ortaya çıkması Mendel\'in hangi ilkesini doğrudan gösterir?', 'Ayrılma ilkesini', ['Bağımsız açılım ilkesini', 'Bağlı kalıtım ilkesini', 'Eksik baskınlık ilkesini'], 'Aa bireyin A ve a gametlerini eşit oranda oluşturması, iki alelin gametlere ayrıldığını gösterir.'),
  ('Dihibrit bir test çaprazlamasında (AaBb × aabb) 1 : 1 : 1 : 1 oranının ortaya çıkması hangi ilkeyi doğrudan destekler?', 'Bağımsız açılım ilkesini', ['Baskınlık ilkesini', 'Eş baskınlık ilkesini', 'Eşeye bağlı kalıtım ilkesini'], 'Dört gamet çeşidinin eşit oranda oluşması, iki genin alellerinin gametlere birbirinden bağımsız dağıldığını gösterir.'),
  ('Aşağıdakilerden hangisi Mendel\'in ayrılma ilkesine aykırı değildir, yalnız baskınlık ilişkisini değiştirir?', 'Eksik baskınlık', ['Tam bağlı genlerin birlikte kalıtılması', 'Mayozda kromozomların ayrılmaması', 'Mitokondriyal genlerin yalnız anneden geçmesi'], 'Eksik baskınlıkta aleller yine gametlere ayrılır ve F2\'de 1 : 2 : 1 açılım görülür; değişen yalnız heterozigotun fenotipidir.'),
  ('İki baskın alelin aynı kromozomda, iki çekinik alelin homolog kromozomda bulunduğu (AB/ab) dizilime ne ad verilir?', 'Cis dizilim (birlikte dizilim)', ['Trans dizilim (karşı dizilim)', 'Bağımsız dizilim', 'Hemizigot dizilim (tek kopyalı dizilim)'], 'AB/ab dizilimine cis ya da birlikte dizilim (coupling), Ab/aB dizilimine trans ya da karşı dizilim (repulsion) denir.'),
  ('Kendisi belirli bir özelliği belirlemeyen ama başka bir genin fenotipe etkisinin derecesini artıran ya da azaltan genlere ne ad verilir?', 'Değiştirici (modifiye edici) genler', ['Holandrik genler', 'Letal genler', 'Ayrılmayı denetleyen sentromer genleri'], 'Değiştirici genler, ana genin ifadesini etkileyerek aynı ana genotipte farklı fenotip derecelerine yol açabilir.'),
  ('Rh kan grubu sisteminde Rh+ fenotipini belirleyen, alyuvar zarında bulunan ve en güçlü bağışıklık tepkisine yol açan antijen hangisidir?', 'D antijeni', ['A antijeni', 'B antijeni', 'H antijeni'], 'Rh+ ve Rh− ayrımı alyuvarlarda D antijeninin bulunup bulunmamasına göre yapılır; D\'yi belirleyen alel baskındır.'),
  ('Genotipi AaBbCc olan bir bitki kendileştiriliyor (genler bağımsız). 640 dölden yaklaşık kaçının AABBCC genotipinde olması beklenir?', '10', ['40', '80', '160'], 'AABBCC olasılığı (1/4)³ = 1/64\'tür; 640 × 1/64 = 10.'),
  ('Bir dihibrit problemde öğrenci, A ve B genlerinin aynı kromozomda yakın konumda olduğu söylendiği hâlde 9 : 3 : 3 : 1 oranını kullanıyor. Öğrencinin hatası nedir?', 'Bağlı genlerin bağımsız açılmadığını unutması', ['Baskınlığın tam olduğunu varsayması', 'Genlerin X kromozomunda bulunduğunu ve eşeye bağlı kalıtıldığını unutması', 'Gamet sayısını dört yerine iki alması'], '9 : 3 : 3 : 1 yalnız bağımsız açılan genler için geçerlidir; yakın bağlı genlerde ebeveyn birleşimleri baskın çıkar.'),
  ('Genleri bağımsız açılan AaBbCcDdEe genotipli bir bireyin aBcDe genotipli bir gamet oluşturma olasılığı nedir?', '1/32', ['1/10', '1/16', '1/128'], 'Beş lokusun her birinde belirli bir alelin gamete geçme olasılığı 1/2\'dir: (1/2)⁵ = 1/32.'),
  ('AaBbCc × AaBbCc gibi çok genli çaprazlamaların çözümünde Punnett karesi yerine çarpım kuralı ya da dallanma (çatal) yönteminin tercih edilmesinin nedeni nedir?', 'Punnett karesinin çok büyümesi', ['Punnett karesinin bağımsız açılan genlerde her zaman yanlış sonuç vermesi', 'Çarpım kuralının yalnızca bağlı genlerde geçerli olması', 'Punnett karesinin yalnız bitkilerde kullanılabilmesi'], 'Bağımsız genlerde her lokus ayrı hesaplanıp olasılıklar çarpılabilir; bu, 8 × 8\'lik kareyi doldurmaktan çok daha hızlı ve güvenilirdir.'),
  ('Aralarında tam baskınlık sırası bulunan dört alelli bir dizide (A1 > A2 > A3 > A4) popülasyonda kaç farklı fenotip görülebilir?', '4', ['10', '6', '16'], 'Her fenotip, bireyin taşıdığı en baskın alele göre belirlenir; dört alel dört fenotip verir (genotip sayısı ise 10\'dur).'),
  ('ABO kan grubu sisteminde olası genotip sayısı ile fenotip sayısı sırasıyla kaçtır?', '6 ve 4', ['4 ve 4', '3 ve 4', '6 ve 6'], 'Üç alelle 6 genotip (I^AI^A, I^Ai, I^BI^B, I^Bi, I^AI^B, ii) oluşur; I^A ve I^B\'nin i\'ye baskınlığı nedeniyle bunlar 4 fenotipte toplanır.'),
  ('Taşıyıcısını üreme çağından önce öldüren baskın letal alellerin popülasyonlarda neredeyse hiç görülmemesinin nedeni nedir?', 'Alelin, taşıyıcılar üremeden öldüğü için hemen elenmesi', ['Baskın letal alellerin hiç oluşmaması', 'Bu alellerin yalnız erkeklerde bulunması ve kızlara hiç geçmemesi', 'Bu alellerin çekinik alellere dönüşmesi'], 'Heterozigotlar da öldüğünden alelin saklanabileceği sağlıklı taşıyıcı yoktur; bu aleller ancak yeni mutasyonlarla ortaya çıkıp hemen kaybolur.'),
  ('Thomas Hunt Morgan, X\'e bağlı kalıtımı ortaya koymasını sağlayan beyaz gözlü mutant erkek meyve sineğini hangi yıl bulmuştur?', '1910', ['1866', '1900', '1953'], 'Morgan 1910\'da kırmızı gözlü sinekler arasında beyaz gözlü bir erkek fark etmiş ve çaprazlamalarıyla göz rengi geninin X\'te olduğunu göstermiştir.'),
  ('A ve B kan gruplu ebeveynlerin ilk çocukları 0 kan grubundandır. Bu ailenin ikinci çocuğunun AB kan grubundan olma olasılığı nedir?', '1/4', ['1/2', 'Sıfır', '1/8'], '0 grubu çocuk, ebeveynlerin I^A i ve I^B i olduğunu gösterir; AB çocuk için anneden ve babadan baskın aleller gelmeli: 1/2 × 1/2 = 1/4.'),
  ('İki genin aynı kromozomda bağlı olup olmadığını anlamak isteyen bir araştırmacı için en uygun deney hangisidir?', 'Çift heterozigotu çift çekinikle çaprazlayıp 1 : 1 : 1 : 1\'den sapmaya bakmak', ['Bireyleri farklı sıcaklıklarda yetiştirmek', 'Yalnız F1 bireylerinin fenotipine bakmak', 'Yalnız bir geni taşıyan bireyleri kendi aralarında çaprazlayıp F1 fenotiplerini saymak'], 'Bağımsız genlerde test çaprazlaması dört sınıfı eşit verir; ebeveyn tiplerinin belirgin fazlalığı bağlılığı gösterir.'),
  ('Bir bitkide ortaya çıkan cüce fenotipin kalıtsal mı yoksa çevresel mi olduğunu anlamak için en uygun yaklaşım hangisidir?', 'Normal bitkiyle çaprazlayıp döllerde açılımı aynı koşullarda izlemek', ['Cüce bitkiye daha çok gübre verip büyüyüp büyümediğine bakmak', 'Cüce bitkinin yapraklarını sayıp normal bitkinin yaprak sayısıyla karşılaştırmak', 'Cüce bitkiyi hemen yok etmek'], 'Fenotip döllerde Mendel oranlarıyla yeniden ortaya çıkıyorsa kalıtsaldır; aynı koşullarda yetiştirme çevre etkisini dışlar.'),
  ('Arabidopsis thaliana adlı küçük bitkinin bitki genetiğinde model organizma olarak yaygın kullanılmasının nedenlerinden biri hangisidir?', 'Yaşam döngüsünün kısa ve genomunun küçük olması', ['Ağaç boyutuna ulaşması', 'Yalnız eşeysiz üremesi', 'Yılda bir kez, ancak çok büyük ve az sayıda tohum oluşturması'], 'Arabidopsis birkaç haftada tohum verir, çok sayıda tohum üretir, kendine döllenebilir ve genomu küçüktür.'),
  ('Hem renk körü hem albino bir erkek, iki özellik için de normal homozigot bir kadınla evleniyor. Çocuklardan hangileri her iki özelliğin alelini de taşır?', 'Bütün kızlar', ['Bütün oğullar', 'Bütün çocuklar', 'Yalnız oğulların yarısı'], 'Bütün çocuklar babadan albinizm aleli alır (Aa); ancak X\'teki renk körlüğü aleli yalnız kızlara geçer. Oğullar babadan Y alır.'),
  ('Sığırlarda kırçıl renk eş baskın (KB), boynuzsuzluk ise boynuzluluğa baskındır (P > p); genler bağımsızdır. KB Pp × KB Pp çiftleşmesinden doğan bir buzağının kırçıl ve boynuzsuz olma olasılığı nedir?', '3/8', ['3/16', '1/4', '9/16'], 'Kırçıl olma 1/2, boynuzsuz olma 3/4: 1/2 × 3/4 = 3/8.'),
  ('\'Saf döl bireyler her zaman baskın fenotipli bireylerdir\' ifadesi neden yanlıştır?', 'Çekinik homozigotlar da hep aynı özelliği verir', ['Saf döl bireyler her zaman heterozigottur', 'Saf döl kavramı yalnız hayvanlarda kullanılır', 'Baskın fenotipli bireyler hiçbir zaman saf döl olamaz, ancak melez olabilir'], 'Saf döl homozigot demektir; aa bireyler de yalnız aa döl verdiğinden saf döldür.'),
  ('AaBb × AaBb çaprazlamasında (genler bağımsız, baskınlık tam) döllerin kaçta kaçı iki karakterden yalnız birinde baskın fenotip gösterir?', '3/8', ['1/4', '9/16', '1/8'], 'Yalnız A baskın (A_bb) 3/16, yalnız B baskın (aaB_) 3/16\'dır; toplam 6/16 = 3/8.'),
  ('AaBbCc × aabbCc çaprazlamasında (genler bağımsız, baskınlık tam) döllerin kaçta kaçı A ve C bakımından baskın, B bakımından çekinik fenotiptedir?', '3/16', ['1/8', '9/32', '3/32'], 'A_: 1/2, bb: 1/2, C_: 3/4; çarpım 1/2 × 1/2 × 3/4 = 3/16.'),
  ('Mendel\'in bağımsız açılım ilkesinin hücresel temeli mayozdaki hangi olaydır?', 'Homolog çiftlerinin metafaz I\'de rastgele dizilmesi', ['Kardeş kromatitlerin mayoz II\'de birbirinden ayrılıp aynı hücrede kalması', 'DNA\'nın interfazda eşlenmesi', 'Sitoplazmanın eşit bölünmemesi'], 'Her homolog çiftin hangi kutba hangi üyesini göndereceği öteki çiftlerden bağımsızdır; bu yüzden farklı kromozomlardaki genler bağımsız açılır.'),
  ('Fenilketonürili ve tedavi almayan bireylerde deri ve saçın genellikle açık renkli olması, aynı gen bozukluğunun hangi özelliğini gösterir?', 'Pleiotropik etkisini', ['Eş baskınlığını', 'Eşeye bağlı olduğunu', 'Eksik penetrans ve ekspresivitesini'], 'Fenilalanin hidroksilaz eksikliği hem sinir sistemini etkiler hem de tirozin ve dolayısıyla melanin üretimini azaltır; tek gen birden çok özelliği etkiler.'),
  ('Bir hastalığın kalıtım biçimi bilinmiyor. Hasta bir babanın oğluna hastalığı aktardığı gözleniyor. Bu bilgi hangi kalıtım biçimini dışlamaz?', 'Otozomal baskın', ['X\'e bağlı çekinik', 'X\'e bağlı baskın', 'Mitokondriyal'], 'Babadan oğula aktarım, X\'e bağlı kalıtımı (oğul babadan Y alır) ve mitokondriyal kalıtımı (yalnız anneden) dışlar; otozomal kalıtımla uyumludur.'),
  ('Bağımsız açılan iki gen için AaBb genotipli bir bireyin gametlerinden kaçta kaçı en az bir çekinik alel taşır?', '3/4', ['1/4', '1/2', '1/16'], 'Gametler AB, Ab, aB, ab\'dir ve eşit oranlıdır; yalnız AB hiç çekinik alel taşımaz: 1 − 1/4 = 3/4.'),
  ('Bağımsız açılan ve tam baskınlık gösteren beş gen bakımından heterozigot bir bitki kendileştirilirse döllerde kaç farklı fenotip görülebilir?', '32', ['10', '243', '25'], 'Her gen için iki fenotip vardır; beş bağımsız gen için 2⁵ = 32 fenotip oluşur (genotip sayısı ise 3⁵ = 243\'tür).'),
  ('Hemofili hastası bir erkeğin kızı sağlıklı ve taşıyıcı olmayan bir erkekle evleniyor. Bu evlilikten doğacak bir kız torunun taşıyıcı olma olasılığı nedir?', '1/2', ['1/4', '1', 'Sıfır'], 'Hasta erkeğin kızı zorunlu taşıyıcıdır; kendi kızlarına hemofili alelini 1/2 olasılıkla aktarır.'),
  ('Mendel\'in ayrılma ilkesi, bir gametin her karakter için yalnız bir alel taşıdığını vurgulayan hangi adla da anılır?', 'Gametlerin saflığı ilkesi', ['Bağımsız açılım ve rastgele birleşme ilkesi', 'Baskınlık ilkesi', 'Eş baskınlık ilkesi'], 'Ayrılma ilkesine göre aleller gamet oluşumunda birbirinden ayrılır ve her gamet bir karakter için \'saf\' olarak tek alel taşır.'),
  ('Manx kedilerinde kuyruksuzluk aleli heterozigotlarda kuyruksuzluk oluşturur, homozigot embriyolar ise gelişemez. Yetiştiricilerin saf döl kuyruksuz bir Manx hattı oluşturamamasının nedeni nedir?', 'Yaşayan kuyruksuzların tümünün heterozigot olması', ['Kuyruksuzluk alelinin çekinik olması', 'Kuyruksuz kedilerin kısır olması', 'Kuyruksuzluğun gebelikteki çevre koşullarıyla oluşup kalıtılmaması'], 'Yaşayan kuyruksuz kediler hep Mm\'dir; Mm × Mm çiftleşmesinde yaşayan yavruların 1/3\'ü kuyruklu (mm) olur.'),
  ('Otozomal çekinik hastalığı olan bir kadın, aynı hastalık için taşıyıcı bir erkekle evleniyor. İlk iki çocuklarının ikisinin de sağlıklı olma olasılığı nedir?', '1/4', ['1/2', '1/16', '3/4'], 'aa × Aa çaprazlamasında her çocuğun sağlıklı (Aa) olma olasılığı 1/2\'dir: 1/2 × 1/2 = 1/4.'),
  ('Soyağacında köşeli parantez içine alınmış bir simge genellikle neyi gösterir?', 'Evlat edinilmiş bireyi', ['Hasta bireyi', 'İkiz bireyi', 'Akraba evliliği yapmış bireyi'], 'Standart gösterimde köşeli parantez, bireyin aileye evlat edinme yoluyla katıldığını belirtir; bu kişinin genleri aileden gelmez.'),
  ('Otozomal baskın bir hastalığı olan heterozigot bir kişinin torununun (çocuğu ve torunu sağlıklı kişilerle evleniyor) bu hastalık alelini taşıma olasılığı nedir?', '1/4', ['1/2', '1/8', '1/16'], 'Alelin çocuğa geçme olasılığı 1/2, çocuktan toruna geçme olasılığı 1/2\'dir: 1/2 × 1/2 = 1/4.'),
  ('Süt verimi yalnız ineklerde ölçülebildiği hâlde boğaların süt verimi genleri bakımından değerlendirilebilmesi hangi yöntemle sağlanır?', 'Kızlarının süt verimine bakılarak', ['Boğanın kendi süt veriminin hormon uygulamasıyla ölçülmesiyle', 'Boğanın boynuz yapısına bakılmasıyla', 'Boğanın ağırlığının ölçülmesiyle'], 'Eşeye sınırlı bir özellik için erkek bireyin genetik değeri, ancak bu özelliği gösteren dişi döllerinin performansından tahmin edilebilir.'),
  ('Buğday ve bezelye gibi kendine döllenen bitki türleri ile mısır gibi yabancı döllenen türler karşılaştırıldığında genel olarak hangisi doğrudur?', 'Kendine döllenenlerde bireylerin çoğu homozigottur', ['Kendine döllenen türlerde heterozigotluk her kuşak artar', 'Yabancı döllenen türlerde bireyler hep saf döldür', 'İki grupta da heterozigotluk oranı aynıdır'], 'Sürekli kendileştirme heterozigotluğu her kuşak yarıya indirir; yabancı döllenme ise farklı alellerin birleşmesini sürdürür.'),
  ('Mendel\'in çalışmalarının 1900\'de yeniden keşfedildiği sırada Mendel ile ilgili hangisi doğrudur?', '1884\'te, yani 16 yıl önce ölmüş olduğu', ['Viyana Üniversitesi\'nde ders verdiği', 'Bulgularını Nobel ödülüyle taçlandırdığı', 'Morgan ile birlikte New York\'ta meyve sineği çalıştığı'], 'Mendel 1884\'te öldü; yasalarının önemi ancak 1900\'de Correns, de Vries ve Tschermak\'ın çalışmalarıyla anlaşıldı.'),
  ('Bahçe bezelyesinin vücut hücrelerinde 14 kromozom bulunur. Bu bitkide kaç bağlantı grubu vardır?', '7', ['14', '28', '2'], 'Bağlantı grubu sayısı haploit kromozom sayısına eşittir; 2n = 14 olan bezelyede n = 7 bağlantı grubu bulunur.'),
  ('Erkek soy hatlarının (baba tarafı atalarının) izlenmesinde Y kromozomunun büyük bölümünün kullanılmasının nedeni nedir?', 'Rekombinasyonsuz olarak babadan oğula geçmesi', ['Y kromozomunun en çok geni taşıyan kromozom olması', 'Y kromozomunun anneden kalıtılması', 'Y kromozomunun her kuşak değişmesi'], 'Y\'nin büyük kısmı X ile eşleşmez ve krossing-over yapmaz; mutasyonlar dışında kuşaklar boyunca değişmeden kalır.'),
  ('X\'e bağlı çekinik bir hastalık için taşıyıcı bir kadın sağlıklı bir erkekle evli. İki oğullarından tam olarak birinin hasta olma olasılığı nedir?', '1/2', ['1/4', '3/4', '1/16'], 'Her oğlun hasta olma olasılığı 1/2\'dir; tam birinin hasta olması için iki sıra vardır: 2 × 1/2 × 1/2 = 1/2.'),
  ('Taşıyıcılık testlerinin yaygınlaşması ve evlilik öncesi taramaların, otozomal çekinik bir hastalığın bir toplumdaki yeni doğan sıklığını azaltabilmesinin temel nedeni nedir?', 'Taşıyıcı çiftlerin bilinçli karar alabilmesi', ['Taramanın taşıyıcıların genlerini değiştirmesi', 'Taşıyıcıların hastalığa yakalanmasının önlenmesi', 'Hastalık alelinin taramayla popülasyondan hemen silinmesi'], 'Tarama genleri değiştirmez; riskli eşleşmeleri belirleyerek danışmanlık ve doğum öncesi tanı seçeneklerinin kullanılmasını sağlar.'),
  ('Aa × Aa çaprazlamasından rastgele seçilen dört yavrunun dördünün de baskın fenotipli olma olasılığı nedir?', '81/256', ['3/4', '27/64', '243/1024'], 'Her yavrunun baskın fenotipli olma olasılığı 3/4\'tür; dört bağımsız yavru için (3/4)⁴ = 81/256.'),
  ('AaBb × AaBb çaprazlamasından (genler bağımsız) rastgele seçilen bir dölün en az bir lokusta homozigot olma olasılığı nedir?', '3/4', ['1/4', '1/2', '9/16'], 'İki lokusta da heterozigot olma olasılığı 1/2 × 1/2 = 1/4\'tür; en az birinde homozigot olma 1 − 1/4 = 3/4.'),
  ('Renk körü bir kadın normal görüşlü bir erkekle evleniyor. İlk iki çocuklarının ikisinin de renk körü olma olasılığı nedir?', '1/4', ['1/2', '1/16', 'Sıfır'], 'Bu ailede yalnız oğullar renk körü olur; her çocuğun oğul olma olasılığı 1/2 olduğundan 1/2 × 1/2 = 1/4.'),
  ('Hemofili taşıyıcısı bir kadın hemofili hastası bir erkekle evleniyor. Doğacak çocuğun hem sağlıklı hem de taşıyıcı olmayan bir kız olma olasılığı nedir?', 'Sıfır', ['1/4', '1/8', '1/2'], 'Baba X\'ini bütün kızlarına verir ve bu X hemofili alelini taşır; bu yüzden kızların hepsi en azından taşıyıcıdır.'),
  ('X\'e bağlı baskın bir hastalık için heterozigot hasta bir kadın, aynı hastalığı gösteren bir erkekle evleniyor. Doğacak çocuğun sağlıklı bir oğul olma olasılığı nedir?', '1/4', ['Sıfır', '1/2', '1/8'], 'Oğullar babadan Y, anneden X alır; sağlıklı olması için annenin normal X\'ini alması gerekir: 1/2 (oğul) × 1/2 = 1/4.'),
  ('X\'e bağlı çekinik ve erkeklerde ölümcül bir alel taşıyan bir kadın sağlıklı bir erkekle evleniyor. Yaşayan kız çocuklarının kaçta kaçı bu aleli taşır?', '1/2', ['1/4', '2/3', '1/3'], 'Kızların tümü yaşar (babadan normal X alırlar) ve anneden alel alma olasılıkları 1/2\'dir.'),
  ('Mendel\'in çaprazlamalarına saf döl ebeveynlerle başlamasının yöntem açısından en önemli yararı neydi?', 'Ebeveynlerin genotiplerini kesin olarak bilmek', ['Döllerin daha çok tohum vermesini sağlamak', 'Mutasyonların ortaya çıkma sıklığını artırmak', 'Çevrenin bitkiler üzerindeki etkisini artırıp ölçmek'], 'Saf döl bireyler homozigottur; böylece F1 ve F2\'deki sonuçlar bilinen genotiplerden yola çıkarak yorumlanabilir.'),
  ('Mendel bezelyede bir çaprazlamayı ebeveynlerin rolleri değiştirilerek yaptığında da aynı sonuçları aldı. Bu bulgu incelediği genler için neyi gösterir?', 'İki ebeveynin döllere eşit katkı yaptığını', ['Genlerin yalnız anneden kalıtıldığını', 'Genlerin yalnız erkek gametlerle, polen tüpü aracılığıyla taşındığını', 'Genlerin sitoplazmada bulunduğunu'], 'Otozomal çekirdek genlerinde iki ebeveyn birer alel verdiğinden resiprokal çaprazlamalar aynı sonucu verir.'),
  ('Bazı ders kitaplarında Mendel\'in ilk ilkesi olarak verilen ve farklı saf döl ebeveynlerin çaprazlanmasıyla elde edilen F1 bireylerinin hepsinin aynı fenotipte olmasını anlatan ilke hangisidir?', 'Tekdüzelik (uniformite) ilkesi', ['Bağımsız açılım ilkesi', 'Bağlı kalıtım ilkesi', 'Eşeye bağlı kalıtım ve hemizigotluk ilkesi'], 'Tekdüzelik ilkesine göre iki farklı saf döl ebeveynin bütün F1 dölleri aynı genotipe (heterozigot) ve aynı fenotipe sahiptir.'),
  ('Mendel, F1 bireylerinin çekinik ebeveynle çaprazlanmasında 1 : 1 oranı çıkacağını deneyi yapmadan önce öngörmüş ve deney bu öngörüyü doğrulamıştır. Bu durum bilimsel yöntem açısından neden önemlidir?', 'Hipotezin öngörüsünün yeni bir deneyle sınanması', ['Deneyin hiç yapılmasına gerek kalmaması', 'Sonucun önceden bilindiği için deneyin geçersiz sayılması', 'Hipotezin gözlem yapılmadan kanıtlanması'], 'Bilimsel bir model yalnız eldeki verileri açıklamakla kalmaz, yeni deneylerin sonuçlarını da doğru öngörür.'),
  ('Mendel\'in \'her birey bir karakter için iki kalıtım birimi taşır\' varsayımına ulaşmasında en belirleyici gözlem hangisidir?', 'Çekinik özelliğin F2\'de değişmeden yeniden çıkması', ['F1 bireylerinin her iki ebeveynden de daha uzun boylu ve daha verimli olması', 'Bitkilerin kendi kendini dölleyebilmesi', 'Tohumların farklı renklerde olabilmesi'], 'F1 bireylerinin görünmeyen bir özelliği gizlice taşıması gerekiyordu; bu, her bireyde iki birim bulunduğu ve bunların gametlerde ayrıldığı fikrini doğurdu.'),
  ('Kuşlarda dişi civcivler Z kromozomlarını hangi ebeveynden alır?', 'Babadan', ['Anneden', 'Yarı yarıya iki ebeveynden', 'Hiç Z kromozomu taşımazlar'], 'Dişiler ZW\'dir; W\'yi anneden, tek Z\'lerini ise babadan alırlar. Bu durum memelilerde erkeklerin X\'i anneden almasına benzer.'),
  ('Bir işverenin iş başvurusu yapanlardan genetik yatkınlık testleri istemesinin en çok tartışılan etik sakıncası nedir?', 'Genetik risklere dayalı ayrımcılık yapılabilmesi', ['Testlerin kan grubunu değiştirmesi', 'Testlerin genleri kalıcı olarak bozması', 'Testlerin yalnız erkeklere uygulanabilmesi'], 'Genetik yatkınlık kesinlik bildirmez; bu bilgilerin işe alım ya da sigortada kullanılması haksız ayrımcılığa yol açabilir.'),
  ('Mendel\'in ayrılma ve bağımsız açılım ilkeleri bakterilerde neden doğrudan uygulanamaz?', 'Bakteriler mayoz ve döllenmeyle eşeyli üremediği için', ['Bakterilerde DNA bulunmadığı için', 'Bakterilerin genlerinin tümü baskın olduğu ve çekinik alel taşımadıkları için', 'Bakteriler çok büyük oldukları için'], 'Mendel ilkeleri diploit canlılarda mayozda homologların ayrılmasına dayanır; bölünerek çoğalan, haploit genomlu bakterilerde bu süreç yoktur.'),
  ('Tekrarlayan ateş ve karın ağrısı ataklarıyla seyreden, Türkiye\'de ve Doğu Akdeniz toplumlarında sık görülen otozomal çekinik hastalık hangisidir?', 'Ailesel Akdeniz ateşi', ['Hemofili A', 'Huntington hastalığı', 'Marfan sendromu'], 'Ailesel Akdeniz ateşi (FMF) MEFV genindeki mutasyonlardan kaynaklanır ve Türk, Ermeni, Arap ve Yahudi toplumlarında sık görülür.'),
  ('Türkiye\'de orak hücre aleli taşıyıcılığının en sık görüldüğü bölge, geçmişte sıtmanın da yaygın olduğu hangi bölgedir?', 'Çukurova', ['Doğu Karadeniz', 'İç Anadolu\'nun kuzeyi', 'Trakya\'nın iç kesimleri'], 'Orak hücre aleli Adana, Mersin ve Hatay\'ı kapsayan Çukurova\'da sık görülür; heterozigotların sıtmaya direnci alelin bu bölgede yaygınlaşmasına katkı sağlamıştır.'),
  ('Kuzen evliliği yapmış bir çiftin oğullarında X\'e bağlı çekinik bir hastalığın görülme riskinin anne tarafındaki taşıyıcılık durumuna bağlı olmasının nedeni nedir?', 'Oğullar X kromozomlarını yalnız anneden aldığı için', ['Oğullar X kromozomunu babadan aldığı için', 'X\'e bağlı genler kuzen evliliğinde Y\'ye geçtiği için', 'Oğullarda iki X kromozomu bulunduğu için'], 'Oğlun hastalanması için annenin X\'lerinden birinin hastalık alelini taşıması yeterlidir; babanın taşıdığı X oğula geçmez.'),
  ('Bir öğrenci \'Bir çocuğun bütün genlerinin tam yarısı anneden, tam yarısı babadan gelir\' diyor. Bu ifade için en doğru düzeltme hangisidir?', 'Otozomal genler için doğrudur; mitokondri DNA\'sı anneden gelir', ['İfade tamamen doğrudur; mitokondri dâhil bütün genler eşit paylaşılır', 'Genlerin dörtte üçü anneden gelir', 'Erkek çocuklar bütün genlerini babadan alır'], 'Otozomların her çiftinin biri anneden biri babadan gelir; ancak mitokondriyal DNA yumurtayla aktarılır ve erkeklerde X anneden, Y babadan gelir.'),
  ('Otozomal çekinik bir hastalık için taşıyıcı iki ebeveynin iki çocuğunun ikisinin de hastalık alelini hiç taşımaması (AA olması) olasılığı nedir?', '1/16', ['1/4', '9/16', '1/8'], 'Aa × Aa\'da her çocuğun AA olma olasılığı 1/4\'tür: 1/4 × 1/4 = 1/16.'),
  ('Yeşil Devrim döneminde Norman Borlaug\'un geliştirdiği yarı cüce buğday çeşitlerinin verimi artırmasının başlıca nedeni nedir?', 'Kısa, sağlam saplarının ağır başakla devrilmemesi', ['Bitkilerin hiç su gereksinmemesi', 'Tohumlarının döllenmeden oluşması', 'Buğdayın çok yıllık bir bitkiye dönüşüp her yıl yeniden ekilmeye gerek kalmaması'], 'Cüceleşme genleri gövde uzamasını azaltır; bol gübreyle büyüyen ağır başaklar devrilmez ve fotosentez ürünlerinin daha büyük kısmı taneye gider.'),
  ('Labrador köpeklerinde ee genotipi B lokusundan bağımsız olarak sarı renk verir. İki sarı labrador çiftleştirildiğinde yavrular için hangisi beklenir?', 'Tamamı sarı olur', ['Yarısı siyah olur', 'Dörtte biri kahverengi olur', 'Siyah, kahverengi ve sarı yavrular 9 : 3 : 4 oranında doğar'], 'İki ebeveyn de ee olduğundan bütün yavrular ee olur ve B alellerinden bağımsız olarak sarı renktedir.'),
  ('\'Doğuştan (konjenital) olan her anomali kalıtsaldır\' ifadesi neden yanlıştır?', 'Gebelikteki çevresel etkenler de anomaliye yol açabilir', ['Doğuştan anomaliler hiçbir zaman genlerle ilgili olmaz', 'Kalıtsal hastalıklar yalnız ileri yaşta ortaya çıkar', 'Konjenital anomaliler yalnız babadan aktarılır'], 'Doğuştan olmak, doğumda var olmak demektir; kızamıkçık enfeksiyonu ya da talidomit gibi çevresel nedenler de doğuştan anomali oluşturur.'),
  ('Kendi kendini dölleyen bir bitkide aa genotipli bir tohum yanlışlıkla AA hattının tarlasına ekiliyor ve çevresindeki AA bitkilerin poleniyle tozlanıyor. Bu bitkinin tohumlarından yetişen döllerin genotipi büyük olasılıkla nedir?', 'Heterozigot (Aa)', ['Homozigot çekinik (aa)', 'Homozigot baskın (AA)', 'Yarısı homozigot baskın, yarısı homozigot çekinik'], 'Bitki yumurta hücrelerine a verir; çevredeki bitkilerin polenleri A taşıdığından yabancı döllenmeyle oluşan tohumlar Aa olur.'),
  ('Bir bitkide kırmızı çiçek (R) beyaza baskın, uzun boy (U) kısaya baskındır ve genler bağımsızdır. Kırmızı-uzun bir bitki beyaz-kısa bir bitkiyle çaprazlanıyor ve döllerin yarısı kırmızı-uzun, yarısı beyaz-uzun çıkıyor. Kırmızı-uzun ebeveynin genotipi nedir?', 'Renk için heterozigot, boy için homozigot', ['Renk için homozigot, boy için heterozigot', 'İki gen için de heterozigot', 'İki gen için de homozigot baskın'], 'Döllerde hiç kısa bitki olmadığına göre ebeveyn UU\'dur; renk için 1 : 1 açılım Rr olduğunu gösterir.'),
  ('AaBbCc × AaBbCc çaprazlamasında (genler bağımsız, baskınlık tam) döllerin kaçta kaçı en az bir karakterde baskın fenotip gösterir?', '63/64', ['27/64', '37/64', '61/64'], 'Üç karakterde de çekinik olma olasılığı (1/4)³ = 1/64\'tür; en az birinde baskın olma 1 − 1/64 = 63/64.'),
  ('Birbirinden bağımsız iki otozomal baskın hastalık için heterozigot olan (AaBb) bir kişi sağlıklı (aabb) biriyle evleniyor. Çocuklarının iki hastalıktan da korunmuş olma olasılığı nedir?', '1/4', ['1/16', '1/2', '9/16'], 'Her hastalık için sağlıklı olma olasılığı 1/2\'dir; ikisinden de korunma 1/2 × 1/2 = 1/4.'),
  ('Son yüz yılda birçok ülkede ortalama insan boyunun birkaç santimetre artması en çok hangi etkenle açıklanır?', 'Beslenme ve sağlık koşullarının iyileşmesiyle', ['Boy genlerinin birkaç kuşakta mutasyonla değişmesiyle', 'Uzun boy alelinin baskın hâle gelmesiyle', 'Boyun artık kalıtılmamasıyla'], 'Popülasyonun gen havuzu birkaç kuşakta bu kadar hızlı değişmez; kalıtsallığı yüksek bir özellik bile çevre iyileştikçe ortalamada artış gösterebilir.'),
  ('HLA haplotipleri blok hâlinde kalıtıldığına göre bir çocuk ile annesi arasındaki HLA uyumu için genellikle hangisi doğrudur?', 'Yarı uyumludurlar; bir haplotip ortaktır', ['Her zaman tam uyumludurlar', 'Hiçbir ortak haplotipleri yoktur', 'Çocuk annesinin iki haplotipini de taşır'], 'Çocuk bir haplotipi anneden, birini babadan alır; bu yüzden ebeveyniyle bir haplotip ortaktır (yarı uyum).'),
  ('Gregor Mendel\'in doğumda aldığı adı nedir ve \'Gregor\' adını ne zaman almıştır?', 'Johann; manastıra girdiğinde', ['Gregor adıyla doğmuştur, ad değiştirmemiştir', 'Josef; üniversiteye başladığında', 'Karl; başrahip seçildiğinde'], 'Johann Mendel 1843\'te Brünn\'deki Augustinusçu manastıra girdiğinde Gregor adını almıştır.'),
  ('Hayvancılıkta suni tohumlamayla tek bir boğanın binlerce yavru vermesinin kalıtım açısından olası bir sakıncası nedir?', 'Genetik çeşitliliğin azalması ve zararlı alellerin yayılması', ['Yavruların tümünün dişi doğması', 'Boğanın genlerinin yavrulara hiç geçmemesi', 'Yavruların kısır doğması'], 'Çok sayıda yavru aynı babadan gelince boğanın taşıdığı çekinik zararlı aleller yaygınlaşır ve sonraki kuşaklarda akrabalı çiftleşme kaçınılmaz hâle gelir.'),
  ('ABO sisteminde alellerin I^A, I^B ve i biçiminde aynı temel harf ve üst simgelerle yazılmasının nedeni nedir?', 'Üçünün de aynı lokusun alelleri olduğunu belirtmek', ['Üç alelin üç farklı kromozomda olduğunu göstermek', 'Alellerin yalnız erkeklerde bulunduğunu belirtmek', 'Alellerin tümünün çekinik olduğunu ve fenotipte görünmediğini göstermek'], 'Çok alelli ya da eş baskın sistemlerde büyük-küçük harf ayrımı yetmez; ortak harf lokusu, üst simgeler alelleri ayırt eder.'),
  ('0 Rh− kan gruplu bir anne ile AB Rh+ (Rr) kan gruplu bir babanın çocuğunun annesiyle aynı kan grubunda (0 Rh−) olma olasılığı nedir?', 'Sıfır', ['1/4', '1/2', '1/8'], 'Baba i aleli taşımadığından çocuk 0 grubu olamaz; Rh bakımından olası olsa bile birleşik olasılık sıfırdır.'),
  ('Farelerde A_C_ aguti, aaC_ siyah, __cc albino fenotip verir. AaCc × AaCc çiftleşmesinden doğan yavruların kaçta kaçı siyah olur?', '3/16', ['9/16', '4/16', '1/16'], 'Siyah için aa (1/4) ve C_ (3/4) gerekir: 1/4 × 3/4 = 3/16.'),
  ('Mendel\'in incelediği bezelye özelliklerinden hangisi çekinik olandır?', 'Sarı bakla rengi', ['Mor çiçek rengi', 'Düz tohum biçimi', 'Uzun gövde'], 'Mendel\'in bezelyelerinde bakla renginde yeşil sarıya baskındır; mor çiçek, düz tohum ve uzun gövde ise baskın özelliklerdir.'),
  ('A Rh+ kan gruplu iki ebeveynin ilk çocuğu 0 Rh− kan grubundandır. Bu ailenin ikinci çocuğunun A Rh+ olma olasılığı nedir?', '9/16', ['3/4', '1/16', '3/16'], '0 Rh− çocuk, ebeveynlerin I^A i Rr olduğunu gösterir; A olma 3/4, Rh+ olma 3/4: 3/4 × 3/4 = 9/16.'),
  ('Ekşi bir yabani elma anacına tatlı bir elma çeşidinden kalem aşılanıyor. Aşılı daldaki çiçeklerin kendi aralarında tozlanmasıyla oluşan tohumlar genetik olarak hangi bitkinin özelliklerini taşır?', 'Kalem olarak aşılanan çeşidin', ['Anaç olarak kullanılan yabani elmanın', 'İki bitkinin eşit karışımının', 'Toprağın türüne göre değişen bir bitkinin'], 'Aşı genleri değiştirmez; çiçek ve tohumlar kalemin dokularından oluştuğu için kalemin genotipini taşır.'),
  ('AaBbCc × aaBbCC çaprazlamasında (genler bağımsız, baskınlık tam) döllerde kaç farklı fenotip görülür?', '4', ['8', '6', '2'], 'A için 2 fenotip (A_ ve aa), B için 2 fenotip (B_ ve bb), C için tek fenotip (hepsi C_) vardır: 2 × 2 × 1 = 4.'),
  ('Farelerde sarı kürk aleli (A^Y) normal alele baskındır ve homozigotta ölümcüldür. Sarı bir fare normal renkli bir fareyle çiftleştirilirse yavrular için hangisi beklenir?', 'Yarısı sarı, yarısı normal renkli olur; embriyo ölümü beklenmez', ['Üçte ikisi sarı olur', 'Dörtte biri ölü doğar', 'Tamamı sarı olur'], 'A^Y a × aa çiftleşmesinde homozigot A^Y A^Y oluşamaz; yavrular 1/2 A^Y a (sarı), 1/2 aa (normal) olur.'),
  ('X\'e bağlı çekinik bir alelin babadan kıza, kızdan da onun oğluna geçmesiyle kuşak atlayarak erkeklerde ortaya çıkması örüntüsüne ne ad verilir?', 'Çapraz (zikzak) kalıtım', ['Holandrik kalıtım', 'Sitoplazmik kalıtım', 'Eşeye sınırlı kalıtım'], 'X\'e bağlı genlerin eşey değiştirerek kuşaktan kuşağa geçmesi çapraz kalıtım olarak adlandırılır.'),
  ('Aa × Aa çaprazlamasının F2\'sinde rastgele seçilen bir bireyin heterozigot olduğu biliniyor. Bu birey çekinik homozigot bir bireyle çaprazlanırsa ilk dölün baskın fenotipli olma olasılığı nedir?', '1/2', ['3/4', '2/3', '1/3'], 'Birey kesin olarak Aa olduğundan Aa × aa çaprazlamasında baskın döl olasılığı 1/2\'dir; F2\'den gelmesi sonucu değiştirmez.'),
  ('Saf döl siyah (BB) ve beyaz (bb) kobayların F1\'i siyahtır. F1 dişileri beyaz erkeklerle, F1 erkekleri de beyaz dişilerle çiftleştiriliyor. Bu iki çiftleşmenin sonuçları için hangisi beklenir?', 'İkisinde de döllerin yarısı siyah, yarısı beyaz olur', ['Birincisinde tamamı siyah, ikincisinde tamamı beyaz olur', 'Yalnız erkek döller beyaz olur', 'İkisinde de 3 siyah : 1 beyaz görülür'], 'Gen otozomal olduğundan resiprokal test çaprazlamaları aynı sonucu verir: Bb × bb, 1 : 1.'),
  ('Bir öğrencinin \'Taşıyıcı bir annenin kızları da X\'e bağlı çekinik hastalığa yakalanır\' önermesini değerlendirmek için sorması gereken en önemli soru hangisidir?', 'Babanın bu hastalık bakımından hasta olup olmadığı', ['Annenin kan grubunun ne olduğu', 'Ailedeki çocuk sayısının kaç olduğu', 'Babanın boyunun ne kadar olduğu'], 'Kızın hasta olması için iki Xᵃ gerekir; bunlardan biri babadan gelir. Baba sağlıklıysa kızlar en çok taşıyıcı olur.'),
  ('Eklemeli genlerle belirlenen bir özellik için iki uç saf hattın F2\'sinde bireylerin 1/64\'ü belirli bir uç ebeveyn fenotipine benziyor. 640 bireylik bir F2\'de iki uç fenotipten herhangi birini gösteren toplam birey sayısı yaklaşık kaçtır?', '20', ['10', '40', '64'], 'Her uç fenotipin oranı 1/64\'tür; iki uç birlikte 2/64 = 1/32 eder: 640 × 1/32 = 20.'),
  ('Aa × Aa evliliğinden doğan beş çocuktan tam olarak ikisinin çekinik fenotipli olma olasılığını hesaplamak için hangi dağılım kullanılır?', 'Binom dağılımı: C(5,2)·(1/4)²·(3/4)³', ['Çarpım kuralı yalnız: (1/4)²', 'Toplama kuralı yalnız: 2/5', 'Binom dağılımı: C(5,2)·(1/2)²·(1/2)³'], 'Çekinik olma olasılığı 1/4, değilse 3/4\'tür. Beş çocuktan ikisinin seçilme yolu C(5,2)=10 olup olasılık 10·(1/16)·(27/64)=270/1024\'tür.'),
  ('Orak hücreli anemi alelinin sıtmanın yaygın olduğu bölgelerde yüksek sıklıkta bulunmasının genetik açıklaması nedir?', 'Heterozigotların sıtmaya karşı görece korunmuş olması', ['Homozigot çekiniklerin sıtmaya dirençli olması', 'Alelin sıtma parazitinin yol açtığı mutasyonla oluşması', 'Homozigot baskınların sıtmadan daha çok ölmesi'], 'Heterozigot bireyler hem ağır anemi geçirmez hem de sıtmaya karşı avantajlıdır; bu heterozigot üstünlüğü zararlı alelin popülasyonda korunmasını sağlar.'),
];
